"""One-time, reproducible editorial upgrade. All text is original synthesis.

Source documents are linked for verification; no affiliation is implied.
The public generator reads content/site-content.json, not legacy HTML.
"""
from pathlib import Path
import json, html as H
ROOT = Path(__file__).resolve().parents[1]
D = json.loads((ROOT/'reference/curated-before-upgrade.json').read_text())
SOURCES = {
 'harvard': ('Harvard Library — HOLLIS Catalog', 'https://library.harvard.edu/services-tools/hollis-catalog'),
 'mit': ('MIT Libraries — Data management', 'https://libraries.mit.edu/data-management/'),
 'dmp': ('MIT Libraries — Write a data management plan', 'https://libraries.mit.edu/data-management/plan/write/'),
 'cornell': ('Cornell Data Services — Data management', 'https://data.research.cornell.edu/data-management/'),
 'readme': ('Cornell Data Services — Writing READMEs for Research Data', 'https://data.research.cornell.edu/data-management/sharing/readme/'),
 'stanford': ('Stanford Libraries — Data support and services', 'https://library.stanford.edu/research-support/data-support-and-services'),
 'oxford': ('Bodleian Libraries — Open access publishing', 'https://www.bodleian.ox.ac.uk/open-research/open-access-publishing'),
 'cambridge': ('University of Cambridge — Apollo', 'https://www.repository.cam.ac.uk/'),
 'uct': ('University of Cape Town — OpenUCT', 'https://open.uct.ac.za/'),
 'pubmed': ('National Library of Medicine — PubMed User Guide', 'https://pubmed.ncbi.nlm.nih.gov/help/'),
 'prisma': ('PRISMA 2020 — Statement and checklists', 'https://www.prisma-statement.org/prisma-2020'),
 'equator': ('EQUATOR Network — Reporting guidelines', 'https://www.equator-network.org/'),
 'consort': ('SPIRIT–CONSORT — Published statements, including the 2025 updates', 'https://www.consort-spirit.org/published-statements'),
 'coreq': ('EQUATOR — COREQ for interviews and focus groups', 'https://www.equator-network.org/reporting-guidelines/coreq/'),
 'prereg': ('Center for Open Science — Preregistration', 'https://www.cos.io/initiatives/prereg'),
 'ucla': ('UCLA Statistical Methods and Data Analytics — G*Power', 'https://stats.oarc.ucla.edu/other/gpower/'),
 'asa': ('American Statistical Association — Statement on p-values', 'https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf'),
 'mice': ('mice for R — Multivariate Imputation by Chained Equations', 'https://amices.org/mice/reference/mice.html'),
 'fair': ('Wilkinson et al. — The FAIR Guiding Principles (2016)', 'https://doi.org/10.1038/sdata.2016.18'),
 'causal': ('Miguel Hernán — Harvard faculty profile and research links', 'https://hsph.harvard.edu/profile/miguel-hernan/'),
 'pew': ('Pew Research Center — Writing Survey Questions', 'https://www.pewresearch.org/writing-survey-questions/'),
 'jupyter': ('JupyterLab — Notebooks', 'https://jupyterlab.readthedocs.io/en/stable/user/notebook.html'),
 'zotero': ('Zotero — Quick start guide', 'https://www.zotero.org/support/quick_start_guide'),
 'orcid': ('ORCID — About ORCID', 'https://info.orcid.org/what-is-orcid/'),
 'crossref': ('Crossref — REST API and metadata', 'https://www.crossref.org/documentation/retrieve-metadata/rest-api/'),
 'datacite': ('DataCite — Persistent identifiers for research', 'https://datacite.org/'),
 'openalex': ('OpenAlex — Help Center', 'https://help.openalex.org/'),
 'doaj': ('DOAJ — About the Directory of Open Access Journals', 'https://doaj.org/about/'),
 'zenodo': ('Zenodo — Research repository', 'https://zenodo.org/'),
 'tcs': ('Think. Check. Submit. — Journal checklist', 'https://thinkchecksubmit.org/journals/'),
 'casp': ('CASP — Critical appraisal checklists', 'https://casp-uk.net/casp-tools-checklists/'),
 'nih': ('NIH — Plan to apply', 'https://grants.nih.gov/grants-process/plan-to-apply'),
 'nihwrite': ('NIH — Write application', 'https://grants.nih.gov/grants-process/write-application'),
 'apa': ('APA Style — Reference examples', 'https://apastyle.apa.org/style-grammar-guidelines/references/examples'),
 'icmje': ('ICMJE — Roles of authors and contributors', 'https://www.icmje.org/recommendations/browse/roles-and-responsibilities/defining-the-role-of-authors-and-contributors.html'),
 'ithenticate': ('iThenticate — Understanding the Similarity Report', 'https://guides.ithenticate.com/hc/en-us/articles/27842305774605-Understanding-the-Similarity-Report'),
 'r': ('The R Project', 'https://www.r-project.org/'),
 'python': ('Python documentation', 'https://docs.python.org/3/'),
}
D['source_registry'] = {k:{'name':v[0],'url':v[1]} for k,v in SOURCES.items()}
D['revision'] = '2026-10-04'
D['new_guides'] = []
def add(slug, category, image, service, related, sources, fa, en, ar):
    for lang, entry in [('fa',fa),('en',en),('ar',ar)]:
        title, description, sections, checklist = entry
        body = ''.join('<h2>'+H.escape(h)+'</h2>'+''.join('<p>'+H.escape(p)+'</p>' for p in paragraphs) for h,paragraphs in sections)
        label={'fa':'چک‌لیست اجرای پژوهش','en':'Practical research checklist','ar':'قائمة تنفيذ البحث'}[lang]
        body+='<h2>'+label+'</h2><ul>'+''.join('<li>'+H.escape(p)+'</li>' for p in checklist)+'</ul>'
        D['articles'][lang].append({'slug':slug,'title':title,'desc':description,'body':body,'category':category,'image':image,'service':service,'related':related,'sources':sources,'revised':'2026-10-04'})
    D['new_guides'].append(slug)

add('fair-open-data','data','desk','data-analysis',['research-data','reproducible-notebooks','open-access'],['fair','cornell','readme','datacite','zenodo'],
('داده FAIR و انتشار مستند؛ مجوز، شناسه و بازاستفاده','داده را با فراداده، README، شناسه پایدار و شرایط دسترسی مستند کنید؛ اصول FAIR را با انتشار آزاد بی‌قیدوشرط یا صرفِ بارگذاری فایل یکسان ندانید.',[
 ('FAIR یک جهت برای مدیریت بهتر است',['این چهار مفهوم به یافتنی‌بودن، دسترس‌پذیری، تعامل‌پذیری و استفاده مجدد اشاره دارند. داشتن یک فایل قابل دانلود به‌تنهایی همه آن‌ها را تأمین نمی‌کند. دسترسی می‌تواند برای داده حساس نیازمند احراز هویت یا مجوز باشد؛ محدودیت دسترسی و روش درخواست باید توضیح داده شوند.']),
 ('فراداده و مستندات',['نام و نسخه مجموعه، مسئول تماس، زمان و مکان گردآوری در حد مجاز، روش تولید، واحدها، کدهای گمشدگی و محدودیت‌ها را ثبت کنید. README یک ورودی خوانا برای انسان است و فراداده ساختاریافته به کشف ماشینی کمک می‌کند. جدول داده بدون تعریف ستون‌ها و منشأ، بازاستفاده را دشوار می‌کند.']),
 ('مجوز و حقوق',['مالکیت، رضایت، تعهدهای پروژه و امکان شناسایی مجدد را قبل از انتشار بررسی کنید. مجوز داده، مجوز کد و وضعیت حقوقی شکل یا متن یکسان نیستند. برای داده‌ای که حق انتشارش را ندارید مجوز دلخواه انتخاب نکنید؛ دسترسی کنترل‌شده یا انتشار مستندات ممکن است مناسب‌تر باشد.']),
 ('مخزن و نسخه',['مخزن موضوعی یا نهادی را با قالب، حجم، پایداری، شرایط سرویس و سیاست محرمانگی مقایسه کنید. شناسه پایدار مانند DOI کشف و استناد را آسان می‌کند، اما صحت علمی داده را تأیید نمی‌کند. شماره نسخه و تفاوت نسخه‌ها را نگه دارید؛ پیوند یک پوشه قابل تغییر با استناد به یک انتشار مشخص برابر نیست.']),
 ('بسته پیشنهادی',['داده مجاز، فرهنگ داده، README، روش پردازش، کد در صورت تناسب و بیانیه دسترسی را در یک انتشار روشن پیوند دهید. در بیانیه، چه چیزی، کجا، با چه نسخه و چه محدودیت‌هایی قابل دریافت است را بنویسید. اگر داده قابل انتشار نیست، دلیل معتبر و مسیر دسترسی مجاز را مشخص کنید و فایل مصنوعی را به‌روشنی برچسب بزنید.'])],['تعریف متغیرها و منشأ ثبت شده‌اند.','حقوق و شرایط دسترسی بررسی شده‌اند.','شناسه و نسخه مشخص‌اند.','بیانیه دسترسی با فایل واقعی تطبیق دارد.']),
('FAIR research data: metadata, licensing and reuse','Document data with metadata, a README, persistent identifiers and access conditions; distinguish FAIR practice from unrestricted sharing or simply uploading a file.',[
 ('What FAIR aims to improve',['Findability, accessibility, interoperability and reuse involve more than offering a download. Sensitive data may require authorization, with restrictions and request procedures explained. FAIR does not imply unrestricted openness.']),
 ('Make documentation useful',['Record the collection title and version, contact, permitted context, methods, units, missing-value codes and limitations. A README supports human understanding while structured metadata supports discovery. Undefined columns and unexplained provenance undermine reuse.']),
 ('Check rights before release',['Review ownership, consent, project obligations and re-identification risks. Data, code, figures and text can have different licensing conditions. Do not assign a license to materials you lack the right to release; controlled access or documentation-only sharing may be appropriate.']),
 ('Choose a repository and version',['Compare disciplinary and institutional repositories for formats, size, preservation, service terms and confidentiality. A DOI supports citation and discovery, not scientific validation. Preserve release versions and changes; a mutable folder link does not identify a stable release.']),
 ('Assemble a coherent package',['Connect permitted data, dictionary, README, processing methods, code where appropriate and an accurate availability statement. Specify location, version and restrictions. Explain valid non-sharing reasons and lawful access routes; label synthetic examples explicitly.'])],['Define variables and provenance.','Check rights and access conditions.','Specify identifier and release version.','Match availability statements to actual files.']),
('بيانات FAIR؛ الوصف والترخيص وإعادة الاستخدام','وثّق البيانات بفراداتهـا وREADME والمعرّفات المستمرة وشروط الوصول، ولا تساوِ FAIR بالنشر غير المشروط أو رفع ملف فقط.',[
 ('أهداف الإدارة الأفضل',['تتجاوز قابلية العثور والوصول والتشغيل البيني وإعادة الاستخدام إتاحة تنزيل ملف. قد تحتاج البيانات الحساسة إلى تصريح مع توضيح القيود ومسار الطلب. لا يعني FAIR الانفتاح دون شروط.']),
 ('توثيق يساعد المستخدم',['سجّل العنوان والنسخة والتواصل والسياق المسموح والطرق والوحدات ورموز الفقد والقيود. يساعد README الفهم البشري وتدعم الفراداتهـا المنظمة الاكتشاف. يصعب إعادة استخدام أعمدة بلا تعريف أو مصدر واضح.']),
 ('الحقوق قبل النشر',['راجع الملكية والموافقة والتزامات المشروع وخطر إعادة التعريف. قد تختلف تراخيص البيانات والكود والأشكال والنص. لا تمنح ترخيصاً لمواد لا تملك حق نشرها؛ قد يكون الوصول المنضبط أو نشر التوثيق أنسب.']),
 ('المستودع والنسخة',['قارن المستودعات التخصصية والمؤسسية من حيث الصيغ والحجم والحفظ والشروط والسرية. يساعد DOI على الاستشهاد والاكتشاف ولا يثبت الصحة العلمية. احفظ نسخ الإصدار والتغييرات؛ رابط مجلد متغير لا يعرّف إصداراً ثابتاً.']),
 ('حزمة مترابطة',['اربط البيانات المسموحة وقاموسها وREADME وطرق المعالجة والكود المناسب وبيان الإتاحة. حدّد الموقع والنسخة والقيود وأسباب عدم المشاركة ومسار الوصول المسموح. سمِّ الأمثلة الاصطناعية بوضوح.'])],['تعريف المتغيرات والمصدر.','فحص الحقوق وشروط الوصول.','تحديد المعرف والنسخة.','مطابقة بيان الإتاحة للملفات.']))

add('open-access','publishing','library','scientific-writing',['journal-submission','fair-open-data','researcher-identifiers'],['oxford','doaj','cambridge','tcs','uct'],
('دسترسی آزاد و حقوق انتشار؛ نسخه پذیرفته‌شده تا مخزن','مسیرهای دسترسی آزاد، نسخه مقاله، دوره منع انتشار، مجوز و هزینه را از قرارداد و سیاست رسمی بررسی کنید؛ آزادبودن خواندن را با حق هر نوع بازاستفاده یکسان ندانید.',[
 ('دسترسی به متن و حق استفاده',['قابل خواندن بودن رایگان مقاله با اجازه ترجمه، بازنشر شکل یا استفاده تجاری یکسان نیست. مجوز و قرارداد انتشار را بخوانید. پیش‌چاپ، نسخه پذیرفته‌شده نویسنده و نسخه نهایی ناشر می‌توانند شرایط مختلفی داشته باشند.']),
 ('دو مسیر رایج',['انتشار در یک نشریه دسترسی آزاد و سپردن نسخه مجاز به مخزن، مسیرهای قابل بررسی‌اند. بعضی نشریات هزینه می‌گیرند و بعضی نمی‌گیرند؛ عنوان «آزاد» به‌تنهایی هزینه یا کیفیت را مشخص نمی‌کند. خدمات و توافق‌های دانشگاهی مانند نمونه آکسفورد لزوماً برای همه دانشجویان جهان قابل استفاده نیستند.']),
 ('انتخاب مخزن',['مخزن نهادی مانند Apollo یا OpenUCT می‌تواند خروجی دانشگاه مربوط را حفظ و معرفی کند. الزامات عضویت، نسخه مجاز، فرمت و دوره منع دسترسی را بررسی کنید. برای دانشجوی خارج از دانشگاه، مشاهده خروجی با مجوز سپردن اثر به همان مخزن متفاوت است.']),
 ('اعتبار و هزینه',['نشریه و ناشر، شیوه داوری، هزینه‌ها، اطلاعات تماس و سیاست‌های اصلاح را از منبع اصلی بررسی کنید. DOAJ برای کشف نشریات دسترسی آزاد مفید است و جای بررسی تناسب علمی را نمی‌گیرد. وعده پذیرش فوری یا نام مشابه یک نشریه مشهور را دلیل اعتبار ندانید.']),
 ('پرونده انتشار',['نسخه پذیرفته‌شده، قرارداد، مجوز، تاریخ مجاز سپردن، بیانیه بودجه و شناسه انتشار را حفظ کنید. پیش از بازنشر شکل یا فایل، شرایط همان مورد را بررسی کنید. در صفحه شخصی و فهرست منابع، نسخه و وضعیت داوری مدرک را روشن بنویسید.'])],['نسخه و مجوز مقاله روشن‌اند.','هزینه و امکان حمایت بررسی شده‌اند.','مخزن و شرایط سپردن مناسب‌اند.','وضعیت داوری و نسخه به‌درستی معرفی شده‌اند.']),
('Open access and publishing rights: versions and repositories','Check open-access routes, article versions, embargoes, licenses and costs in official policies; free reading does not imply unrestricted reuse or universal repository eligibility.',[
 ('Separate access from reuse',['Free reading does not automatically permit translation, figure reuse or commercial redistribution. Check the actual license and agreement. Preprints, accepted manuscripts and publisher versions can have different conditions.']),
 ('Compare routes and costs',['Consider open-access journal publication and depositing an allowed version in a repository. Some journals charge and others do not; openness alone establishes neither price nor quality. University publisher agreements, including Oxford’s arrangements, do not automatically cover all researchers.']),
 ('Check repository eligibility',['Institutional repositories such as Apollo and OpenUCT preserve their communities’ outputs. Review membership, accepted versions, file formats and embargo rules. Reading a repository’s contents does not confer the right to deposit there.']),
 ('Evaluate the publication venue',['Verify publisher identity, peer review, fees, contact details and correction policies. DOAJ helps discover open-access journals but does not replace assessment of scientific fit. Familiar branding and rapid acceptance promises are insufficient evidence of trustworthiness.']),
 ('Keep a rights record',['Preserve the accepted version, agreement, license, deposit date, funding statement and publication identifier. Verify the terms for each reused figure or file. Clearly identify versions and peer-review status when listing your work.'])],['Identify the version and license.','Check fees and possible support.','Verify repository deposit conditions.','Describe review status accurately.']),
('الوصول المفتوح وحقوق النشر؛ النسخ والمستودعات','راجع مسارات الوصول المفتوح ونسخ المقال والحظر والتراخيص والتكلفة من السياسات الرسمية؛ القراءة المجانية لا تعني إعادة استخدام بلا حدود.',[
 ('الوصول ليس الترخيص',['لا تمنح القراءة المجانية تلقائياً حق الترجمة أو إعادة نشر الشكل أو الاستخدام التجاري. اقرأ الترخيص والاتفاق؛ قد تختلف شروط المسودة ونسخة المؤلف المقبولة ونسخة الناشر.']),
 ('قارن المسارات والتكلفة',['يمكن بحث النشر في مجلة مفتوحة وإيداع نسخة مسموحة في مستودع. تفرض بعض المجلات رسوماً وبعضها لا يفرضها؛ الانفتاح وحده لا يثبت السعر أو الجودة. اتفاقات جامعة مثل أكسفورد لا تشمل جميع الباحثين تلقائياً.']),
 ('أهلية الإيداع',['تحفظ مستودعات مثل Apollo وOpenUCT مخرجات مجتمعاتها. راجع العضوية والنسخة والصيغة وفترة الحظر. قراءة الملفات لا تمنح حق إيداع بحثك في المستودع نفسه.']),
 ('تقييم جهة النشر',['تحقق من الناشر والتحكيم والرسوم والتواصل وسياسة التصحيح. يفيد DOAJ في اكتشاف المجلات ولا يستبدل تقييم ملاءمتها العلمية. الاسم المألوف ووعد القبول السريع لا يكفيان للثقة.']),
 ('سجل الحقوق',['احفظ النسخة المقبولة والاتفاق والترخيص وتاريخ الإيداع والتمويل والمعرّف. افحص شروط كل شكل أو ملف معاد استخدامه، ووضّح النسخة وحالة التحكيم عند عرض عملك.'])],['تحديد النسخة والترخيص.','فحص الرسوم والدعم.','التحقق من شروط الإيداع.','عرض حالة التحكيم بدقة.']))

add('researcher-identifiers','publishing','editing','editing',['citation-styles','open-access','journal-submission'],['orcid','crossref','datacite','openalex','zotero'],
('ORCID، DOI و هویت پژوهشگر؛ فراداده بدون اشتباه','شناسه پژوهشگر را از شناسه اثر جدا کنید؛ رکوردها، نسخه، نویسندگان و وابستگی را تطبیق دهید و شناسه معتبر را گواهی کیفیت علمی ندانید.',[
 ('شخص، اثر و سازمان',['ORCID به تشخیص هویت پژوهشگر در میان نام‌های مشابه کمک می‌کند. DOI معمولاً به یک خروجی یا رکورد پژوهشی اشاره دارد؛ این دو جایگزین هم نیستند. یک پایان‌نامه و مقاله حاصل از آن ممکن است دو رکورد و شناسه متفاوت داشته باشند.']),
 ('رکورد صحیح',['نام، ترتیب نویسندگان، عنوان، تاریخ، نوع مدرک و نسخه را با منبع اصلی تطبیق دهید. پژوهشگر می‌تواند کنترل‌هایی برای نمایش اطلاعات ORCID داشته باشد؛ اضافه‌شدن یک رکورد به پروفایل، به‌تنهایی تأیید داوری یا کیفیت آن نیست. وابستگی را با زمان واقعی انجام کار و قواعد نشریه هماهنگ کنید.']),
 ('بررسی DOI',['شناسه را از صفحه ناشر یا مخزن بردارید و از مسیر doi.org باز کنید. Crossref و DataCite فراداده انواعی از خروجی‌های پژوهشی را ارائه می‌کنند. یک DOI که باز می‌شود می‌تواند به مدرکی غیر از مدرک مورد نظر اشاره کند؛ عنوان و نویسندگان را هم بررسی کنید.']),
 ('نام‌های چندزبانه و ادغام',['املای فارسی، عربی و لاتین یک نام را در جاهای لازم هماهنگ ثبت کنید. پروفایل‌های خودکار یا پایگاه‌های کشف ممکن است اشخاص را اشتباه ادغام یا آثار را جدا کنند. اصلاح رکورد را در سامانه مالک انجام دهید و کتابخانه شخصی منابع را پس از ادغام دوباره کنترل کنید.']),
 ('استناد و سنجه‌ها',['شناسه پایدار به پیوند و استناد کمک می‌کند ولی تعداد استناد یا وجود شناسه رتبه کیفیت مستقل نیست. پوشش پایگاه‌ها و تاریخ استخراج سنجه را ثبت کنید. ابزار ساخت پیوند DOI در جعبه‌ابزار فقط قالب پیوند می‌سازد و وجود یا صحت مدرک را تأیید نمی‌کند.'])],['شناسه شخص و اثر جدا هستند.','فراداده با مدرک اصلی تطبیق دارد.','نسخه و وابستگی زمانی روشن‌اند.','رکورد تکراری و اشتباه هویت بررسی شده‌اند.']),
('ORCID, DOI and researcher identity','Distinguish researcher identifiers from output identifiers; reconcile names, authors, versions and affiliations, and avoid treating an identifier as proof of research quality.',[
 ('Different identifiers serve different entities',['ORCID helps distinguish researchers with similar names. A DOI identifies a research output or record; it is not a person identifier. A thesis and its subsequent article may be separate records.']),
 ('Verify the record',['Check author order, title, date, document type and version against the original source. ORCID visibility controls and imported records do not establish that every listed work is peer reviewed. Align affiliations with the actual work and venue requirements.']),
 ('Resolve and compare DOIs',['Copy the identifier from the publisher or repository and follow doi.org. Crossref and DataCite provide metadata for research outputs. Successful resolution alone is insufficient: the title and authors must match the intended reference.']),
 ('Handle multilingual and duplicate names',['Keep necessary Persian, Arabic and Latin name variants consistent. Automatic profiles can merge different people or split one researcher’s works. Correct records in the responsible service and check your reference library again after merging duplicates.']),
 ('Interpret metrics carefully',['Identifiers support linking and citation, not independent quality certification. Record database coverage and extraction dates when reporting metrics. The toolkit’s DOI link builder formats a link; it does not verify that the work exists or is correct.'])],['Separate person and output identifiers.','Match metadata to the original.','Specify version and relevant affiliation.','Check duplicate and mistaken identities.']),
('ORCID وDOI وهوية الباحث','ميّز معرّف الباحث من معرّف العمل، وطابق الأسماء والمؤلفين والنسخ والانتماء، ولا تعتبر المعرّف دليلاً على جودة البحث.',[
 ('معرّفات لكيانات مختلفة',['يساعد ORCID على تمييز الباحثين ذوي الأسماء المتشابهة. يعرّف DOI مخرجاً أو سجلاً ولا يعرّف الشخص. قد تكون الرسالة والمقال المستخرج منها سجلين مستقلين.']),
 ('تدقيق السجل',['طابق ترتيب المؤلفين والعنوان والتاريخ والنوع والنسخة بالمصدر الأصلي. لا تثبت إعدادات ORCID أو السجلات المستوردة تحكيم كل عمل. وائم الانتماء مع ظروف العمل ومتطلبات جهة النشر.']),
 ('فتح DOI ومطابقته',['انسخ المعرّف من الناشر أو المستودع وافتحه عبر doi.org. توفر Crossref وDataCite فراداتهـا لمخرجات بحثية. نجاح الفتح وحده غير كافٍ؛ طابق العنوان والمؤلفين بالمرجع المقصود.']),
 ('الأسماء متعددة اللغات والتكرار',['نسّق صيغ الاسم اللازمة بالفارسية والعربية واللاتينية. قد تدمج الأنظمة أشخاصاً مختلفين أو تفصل أعمال باحث واحد. صحّح السجلات لدى الخدمة المسؤولة وراجع مكتبة المراجع بعد الدمج.']),
 ('تفسير المقاييس',['تدعم المعرّفات الربط والاستشهاد ولا تمنح شهادة جودة. وثّق تغطية القاعدة وتاريخ استخراج المقاييس. تنسّق أداة DOI في صندوق الأدوات رابطاً فقط ولا تتحقق من وجود العمل أو صحته.'])],['فصل معرّف الشخص والعمل.','مطابقة الفراداتهـا بالأصل.','توضيح النسخة والانتماء.','فحص التكرار وأخطاء الهوية.']))

add('reporting-guidelines','writing','scientific-writing','scientific-writing',['systematic-review','qualitative-research','journal-submission'],['equator','consort','prisma','coreq'],
('راهنماهای گزارش پژوهش؛ انتخاب PRISMA، CONSORT و COREQ','راهنمای گزارش را با نوع مطالعه انتخاب کنید؛ PRISMA 2020، CONSORT و SPIRIT 2025 و راهنماهای کیفی را با نسخه و الزامات نشریه تطبیق دهید.',[
 ('گزارش‌دهی با اعتبار روش یکسان نیست',['چک‌لیست کمک می‌کند اطلاعات ضروری از قلم نیفتد، اما اجرای نامناسب مطالعه را درست نمی‌کند. از مرحله طراحی آن را برای پیش‌بینی مدارک لازم بخوانید و هنگام نگارش، محل پوشش هر بند را مشخص کنید. یک گواهی صوری یا تیک بدون شاهد، گزارش شفاف نیست.']),
 ('نوع مطالعه و نسخه',['برای مرور نظام‌مند PRISMA 2020، برای گزارش کارآزمایی تصادفی CONSORT و برای پروتکل مرتبط SPIRIT را بررسی کنید. در منابع رسمی، نسخه‌های ۲۰۲۵ CONSORT و SPIRIT موجودند. برای مطالعه مشاهده‌ای، کیفی، تشخیصی یا گزارش مورد، راهنمای متناسب و افزونه‌های لازم را از EQUATOR پیدا کنید.']),
 ('افزونه و دامنه',['طرح خوشه‌ای، مطالعه پایلوت یا موضوع تخصصی ممکن است افزونه نیاز داشته باشد. نام آشنا کافی نیست؛ دامنه راهنما را با طراحی واقعی تطبیق دهید. COREQ برای مصاحبه و گروه کانونی طراحی شده و برای تمام انواع تحلیل کیفی نسخه واحدی نیست.']),
 ('استفاده عملی',['یک جدول سه‌ستونی بسازید: بند، محل در متن، وضعیت و توضیح. اگر بند کاربرد ندارد دلیل را بنویسید. نمودار جریان، پروتکل، راهبرد جست‌وجو و پیوست‌ها را مطابق نوع مطالعه اضافه کنید و اعداد آن‌ها را با نمونه گزارش‌شده تطبیق دهید.']),
 ('پیش از ارسال',['نسخه و تاریخ دسترسی به راهنما، فایل چک‌لیست تکمیل‌شده و الزامات نشریه را حفظ کنید. اگر نشریه نسخه مشخصی می‌خواهد، تفاوت با راهنمای جدیدتر را شفاف مدیریت کنید. نویسندگان باید بررسی کنند که جدول‌ها و بیانیه‌ها با اجرای واقعی سازگار باشند.'])],['راهنما با طراحی تناسب دارد.','نسخه و افزونه درست انتخاب شده‌اند.','برای هر بند محل یا دلیل عدم کاربرد ثبت شده است.','نمودار و چک‌لیست با متن سازگارند.']),
('Research reporting guidelines: PRISMA, CONSORT and COREQ','Choose reporting guidance by study design; check PRISMA 2020, CONSORT and SPIRIT 2025, qualitative guidance and journal-specific requirements.',[
 ('Reporting is not methodological certification',['A checklist helps prevent omissions but cannot repair an invalid study. Read it during planning and record where each applicable item is addressed. A tick without supporting information is not transparent reporting.']),
 ('Match design and version',['Review PRISMA 2020 for systematic reviews, CONSORT for randomized trial reports and SPIRIT for related protocols. Official sources include the 2025 CONSORT and SPIRIT updates. Use EQUATOR to locate suitable guidance for observational, qualitative, diagnostic and other designs.']),
 ('Check extensions and scope',['Cluster, pilot and specialized studies may require extensions. A familiar acronym is insufficient. COREQ targets interviews and focus groups rather than every qualitative method.']),
 ('Use a coverage table',['Record the item, manuscript location and status or explanation. Explain inapplicable items; add design-appropriate flow diagrams, protocols, search strategies and supplements. Reconcile their counts with the reported sample.']),
 ('Prepare for submission',['Keep the version, access date, completed checklist and journal requirements. Manage differences when a journal specifies another version. Authors must ensure tables and declarations reflect what was actually done.'])],['Match guidance to the design.','Select the appropriate version and extension.','Provide locations or non-applicability reasons.','Reconcile checklists, diagrams and manuscript.']),
('إرشادات تقرير البحث؛ PRISMA وCONSORT وCOREQ','اختر الإرشادات حسب التصميم، وراجع PRISMA 2020 وتحديثات CONSORT وSPIRIT 2025 والإرشادات النوعية ومتطلبات المجلة.',[
 ('التقرير ليس شهادة صحة المنهج',['تمنع القائمة إغفال معلومات لكنها لا تصلح دراسة غير صالحة. اقرأها عند التخطيط وسجّل موضع تغطية كل بند. علامة دون معلومات داعمة لا تحقق الشفافية.']),
 ('تطابق التصميم والنسخة',['راجع PRISMA 2020 للمراجعات المنهجية وCONSORT لتقارير التجارب العشوائية وSPIRIT للبروتوكولات ذات الصلة. تتضمن المصادر الرسمية تحديثات 2025. استخدم EQUATOR للوصول إلى إرشادات الدراسات الرصدية والنوعية والتشخيصية وغيرها.']),
 ('الامتدادات والنطاق',['قد تتطلب الدراسات العنقودية والتجريبية الأولية والمتخصصة امتدادات. لا يكفي اختصار مألوف؛ يستهدف COREQ المقابلات والمجموعات البؤرية وليس كل طريقة نوعية.']),
 ('جدول تغطية عملي',['سجّل البند وموضعه والحالة أو السبب. فسّر عدم الانطباق وأضف مخططات وبروتوكولات واستراتيجيات وملاحق مناسبة. طابق أعدادها مع العينة في التقرير.']),
 ('الاستعداد للإرسال',['احفظ النسخة وتاريخ الوصول والقائمة ومتطلبات المجلة. تعامل بشفافية مع اختلاف النسخة المطلوبة. يجب أن تطابق الجداول والبيانات ما نُفّذ فعلاً.'])],['توافق الإرشادات والتصميم.','اختيار النسخة والامتداد.','تحديد المواضع وأسباب عدم الانطباق.','اتساق القائمة والمخطط والنص.']))

add('grant-planning','design','proposal','proposal',['research-proposal','research-data','preregistration'],['nih','nihwrite','dmp'],
('برنامه‌ریزی گرنت پژوهشی؛ تناسب فراخوان، بودجه و زمان','ایده پژوهش را با دامنه فراخوان و شرایط احراز هماهنگ کنید؛ اهداف، منابع، بودجه مستند، برنامه داده و مهلت‌های داخلی را در یک پرونده قابل بررسی جمع کنید.',[
 ('فراخوان مقدم بر فرم است',['دامنه موضوعی، نوع متقاضی، کشور یا مؤسسه واجد شرایط، نوع هزینه مجاز و مهلت را در متن فعلی فراخوان بخوانید. یک مثال از NIH برای آموزش مسیر درخواست مفید است، اما به معنی واجد شرایط بودن هر دانشجو یا بازبودن فراخوان خاص نیست.']),
 ('هدف و قابلیت اجرا',['پرسش، اهمیت، سهم جدید، اهداف مشخص و ارتباط روش با هر هدف را روشن کنید. داده مقدماتی، امکانات و نقش همکاران را صادقانه معرفی کنید. نتیجه مطلوب آینده را نتیجه به‌دست‌آمده ننویسید.']),
 ('بودجه از پایین به بالا',['هر فعالیت را به منابع، زمان و هزینه قابل توجیه وصل کنید. نرخ‌ها، خرید، سفر، دسترسی نرم‌افزار، مدیریت داده و هزینه‌های نهادی باید با فراخوان و قواعد مؤسسه سازگار باشند. واحد پول، تاریخ مبنای برآورد و فرض‌ها را ثبت کنید؛ این راهنما عدد یا نرخ جاری ارائه نمی‌کند.']),
 ('اسناد و مهلت‌ها',['ثبت حساب، تأیید سازمان، نامه‌های همکاری، رزومه، طرح داده و بررسی داخلی ممکن است زمان جدا بخواهند. یک زمان‌بندی معکوس با حاشیه برای بازبینی و خطای ارسال بسازید. مهلت داخلی مؤسسه و منطقه زمانی سامانه را از مهلت نهایی جدا کنید.']),
 ('بازبینی نهایی',['برای هر معیار ارزیابی، محل شاهد در درخواست را پیدا کنید. سازگاری عنوان، اهداف، بودجه، زمان، تیم و مدیریت داده را کنترل کنید. نسخه نهایی، تأییدها و رسید ارسال را نگه دارید. دریافت گرنت قابل تضمین نیست و ظرفیت و رقابت فراخوان به شرایط واقعی بستگی دارد.'])],['احراز شرایط از متن فعلی بررسی شده است.','هر هدف روش و منابع دارد.','بودجه و فرض‌های قیمت مستندند.','مهلت‌های داخلی و رسید ارسال ثبت شده‌اند.']),
('Research grant planning: fit, budget and timeline','Match the idea to the current funding call and eligibility rules; prepare coherent aims, resources, justified budgets, data plans and internal submission deadlines.',[
 ('Read the opportunity before the form',['Check scope, applicant type, country or institution eligibility, allowable costs and deadline in the current call. NIH guidance illustrates a process; it does not establish eligibility for every student or availability of a particular opportunity.']),
 ('Connect aims to feasibility',['Explain the question, significance, contribution and methods for each aim. Present preliminary evidence, facilities and collaborator roles honestly. Expected future findings are not completed results.']),
 ('Build the budget from activities',['Connect each activity to resources, time and justified costs. Institutional rules and the call govern rates, purchases, travel, software and data-management costs. Record currency, estimate date and assumptions; this guide does not provide current rates.']),
 ('Work backward from deadlines',['Accounts, organizational authorization, letters, CVs, data plans and internal review may require separate lead times. Allow time for revisions and submission problems. Distinguish institutional deadlines and portal time zones from the final deadline.']),
 ('Review a coherent application',['Locate evidence for each review criterion and reconcile title, aims, budget, schedule, team and data planning. Preserve the final version, approvals and submission receipt. Funding decisions depend on the actual opportunity and competition and cannot be guaranteed.'])],['Check current eligibility.','Link aims, methods and resources.','Justify costs and assumptions.','Record internal deadlines and receipt.']),
('تخطيط منحة بحثية؛ الملاءمة والميزانية والوقت','وائم الفكرة مع الدعوة الحالية وشروط الأهلية، وجهّز أهدافاً وموارد وميزانية مبررة وخطة بيانات ومواعيد تقديم داخلية متسقة.',[
 ('الدعوة قبل الاستمارة',['افحص النطاق ونوع المتقدم وأهلية البلد والمؤسسة والتكاليف والموعد في النص الحالي. تشرح إرشادات NIH مساراً ولا تثبت أهلية كل طالب أو توفر فرصة معينة.']),
 ('الأهداف والجدوى',['وضّح السؤال والأهمية والمساهمة وطريقة كل هدف. اعرض الأدلة الأولية والمرافق وأدوار المتعاونين بصدق. النتائج المستقبلية المتوقعة ليست نتائج منجزة.']),
 ('ميزانية مبنية على النشاط',['اربط كل نشاط بالموارد والوقت والتكلفة. تحكم الدعوة والمؤسسة الأسعار والمشتريات والسفر والبرامج وإدارة البيانات. وثّق العملة وتاريخ التقدير والافتراضات؛ لا يقدم هذا الدليل أسعاراً حالية.']),
 ('الوثائق والمواعيد',['قد تتطلب الحسابات والتفويض والخطابات والسير وخطة البيانات والمراجعة الداخلية وقتاً منفصلاً. خطط عكسياً مع وقت للتعديل ومشكلات الإرسال، وميّز المواعيد الداخلية والمناطق الزمنية عن الموعد النهائي.']),
 ('مراجعة اتساق الطلب',['حدّد دليل كل معيار تقييم وطابق العنوان والأهداف والميزانية والجدول والفريق والبيانات. احفظ النسخة والموافقات وإيصال الإرسال. لا يمكن ضمان التمويل؛ يتوقف القرار على الدعوة والمنافسة الفعلية.'])],['فحص الأهلية الحالية.','ربط الأهداف بالموارد والطرق.','تبرير التكاليف والافتراضات.','توثيق المواعيد والإيصال.']))

add('critical-appraisal','search','originality','originality',['literature-search','systematic-review','research-design'],['casp','equator','tcs'],
('خواندن نقادانۀ مقاله؛ اعتبار روش، شواهد و کاربرد','پرسش، طراحی، نمونه، سنجش و تحلیل مقاله را ارزیابی کنید؛ کیفیت گزارش، خطر سوگیری، تناسب کاربرد و وضعیت اصلاح یا پس‌گرفتن را جدا بررسی کنید.',[
 ('خواندن هدفمند',['ابتدا پرسش و ادعای اصلی را پیدا کنید و مشخص کنید مقاله برای تصمیم شما چه نقشی دارد. عنوان، چکیده و نتیجه را با روش و جدول‌ها تطبیق دهید. یک مرور آموزشی را با پژوهش اولیه یا مرور نظام‌مند اشتباه نگیرید.']),
 ('اعتبار و سوگیری',['طرح، انتخاب نمونه، اندازه‌گیری، مقایسه گروه‌ها، زمان‌بندی، گمشدگی و تحلیل را بررسی کنید. از ابزار ارزیابی متناسب با طراحی استفاده کنید؛ یک امتیاز عمومی برای تمام مطالعات می‌تواند تفاوت‌ها را پنهان کند. راهنمای گزارش با ابزار خطر سوگیری یکسان نیست.']),
 ('اعداد و تفسیر',['نمونه تحلیل‌شده را با نمونه گردآوری‌شده تطبیق دهید. اندازه اثر، عدم قطعیت و فرض‌های مدل را ببینید و فقط به معنی‌داری اتکا نکنید. نمودار زیبا یا نام دانشگاه معروف به‌تنهایی اعتبار نتیجه را تضمین نمی‌کند.']),
 ('کاربرد و وضعیت مدرک',['جمعیت، محیط و سنجش مطالعه را با مسئله خود مقایسه کنید. در صفحه ناشر، اصلاحیه یا پس‌گرفتن و وضعیت نسخه را بررسی کنید. پیش‌چاپ را به‌وضوح از نسخه داوری‌شده جدا بنویسید. تعداد استناد بالا می‌تواند به شهرت یا نقد مربوط باشد و جای ارزیابی روش را نمی‌گیرد.']),
 ('دفتر شواهد',['برای هر مدرک، سؤال، طرح، یافته کلیدی، محدودیت، ارزیابی و نقش در استدلال خود را بنویسید. نقل‌قول را از خلاصه و برداشت شخصی جدا نگه دارید. در مرور، مطالعات مخالف را هم ثبت کنید و معیار ورود را پس از دیدن نتیجه مطلوب تغییر ندهید.'])],['ادعا با روش و داده سازگار است.','ابزار ارزیابی با طراحی تناسب دارد.','اثر و محدودیت‌ها ثبت شده‌اند.','نسخه و وضعیت انتشار بررسی شده‌اند.']),
('Critical appraisal: methods, evidence and applicability','Evaluate questions, design, sampling, measurement and analysis; distinguish reporting quality, risk of bias, relevance and the publication’s correction or withdrawal status.',[
 ('Read with a purpose',['Find the central question and claim, and identify the paper’s role in your decision. Reconcile the abstract and conclusion with methods and tables. Distinguish educational reviews, primary studies and systematic evidence syntheses.']),
 ('Assess validity using appropriate tools',['Inspect selection, measurement, comparison, timing, missingness and analysis. Use an appraisal tool suited to the design instead of one generic score for everything. Reporting guidance is not identical to risk-of-bias assessment.']),
 ('Examine estimates and interpretation',['Compare collected and analyzed samples. Read effect estimates, uncertainty and model assumptions rather than significance alone. Attractive figures or a prestigious affiliation do not establish valid findings.']),
 ('Check applicability and document status',['Compare populations, settings and measurement with your own question. Check the publisher for corrections, withdrawal and version status. Clearly label preprints. Citation counts may reflect visibility or criticism, not methodological quality.']),
 ('Keep an evidence record',['Record question, design, key finding, limitations, appraisal and relevance to your argument. Separate quotation, summary and personal interpretation. Retain conflicting evidence and do not change eligibility criteria simply to favor preferred results.'])],['Reconcile claims, design and evidence.','Use a design-appropriate tool.','Record estimates and limitations.','Check versions and publication status.']),
('القراءة النقدية؛ المنهج والأدلة وقابلية التطبيق','قيّم السؤال والتصميم والعينة والقياس والتحليل، وافصل جودة التقرير وخطر التحيز والملاءمة وحالة التصحيح أو السحب.',[
 ('قراءة لغرض واضح',['حدّد السؤال والادعاء ودور المقال في قرارك. طابق الملخص والخاتمة بالطرق والجداول، وميّز المراجعة التعليمية والدراسة الأولية والتركيب المنهجي للأدلة.']),
 ('تقييم مناسب للتصميم',['افحص الاختيار والقياس والمقارنة والتوقيت والفقد والتحليل. اختر أداة ملائمة بدلاً من درجة عامة لكل الدراسات. تختلف إرشادات التقرير عن تقييم خطر التحيز.']),
 ('التقديرات والتفسير',['قارن العينة المجموعة بالمحللة واقرأ الأثر وعدم اليقين والافتراضات، لا الدلالة فقط. لا يثبت رسم جميل أو انتماء مرموق صحة النتيجة.']),
 ('الملاءمة وحالة الوثيقة',['قارن السكان والبيئة والقياس بسؤالك. افحص لدى الناشر التصحيح والسحب وحالة النسخة. ميّز المسودة الأولية بوضوح؛ قد يعكس عدد الاستشهادات الشهرة أو النقد لا جودة المنهج.']),
 ('سجل الأدلة',['وثّق السؤال والتصميم والنتيجة والقيود والتقييم والصلة بحجتك. افصل الاقتباس والخلاصة والتفسير الشخصي. احفظ الأدلة المخالفة ولا تغيّر معايير الأهلية لتفضيل نتيجة مرغوبة.'])],['اتساق الادعاء والتصميم والأدلة.','أداة مناسبة للتصميم.','تسجيل التقديرات والقيود.','فحص النسخة وحالة النشر.']))

add('effect-size-uncertainty','analysis','data-analysis','data-analysis',['sample-size-power','missing-data','statistical-software'],['asa','ucla'],
('اندازه اثر، فاصله اطمینان و p-value؛ گزارش مسئولانه','در کنار آزمون معنی‌داری، جهت و اندازه اثر، واحد، فاصله اطمینان و محدودیت طراحی را گزارش کنید؛ نبود معنی‌داری را با نبود اثر یکسان ندانید.',[
 ('سؤال عملی را حفظ کنید',['خواننده باید بداند اختلاف یا رابطه چقدر است و برای مسئله چه معنایی دارد. اختلاف میانگین را با واحد واقعی، نسبت‌ها را با جمعیت و زمان مرتبط و ضرایب مدل را با تعریف متغیرها توضیح دهید. مقدار استانداردشده برای مقایسه مفید است، اما می‌تواند معنای واحد اصلی را پنهان کند.']),
 ('p-value چه نمی‌گوید؟',['طبق بیانیه ASA، p-value به‌تنهایی احتمال درست‌بودن فرض صفر، اندازه اثر یا اهمیت علمی را تعیین نمی‌کند. تصمیم پژوهشی را به عبور از یک آستانه محدود نکنید. مقدار کوچک می‌تواند برای اثری کم‌اهمیت و مقدار بزرگ برای برآوردی نامطمئن رخ دهد؛ اندازه نمونه و طراحی نیز مهم‌اند.']),
 ('عدم قطعیت و فرض‌ها',['برآورد را همراه با فاصله اطمینان و روش محاسبه ارائه کنید. در تفسیر فراوانی‌گرایانه، پوشش به رفتار روش در نمونه‌گیری تکراری مربوط است؛ نگویید پس از محاسبه، پارامتر ثابت با احتمال همان درصد داخل فاصله است. فروض مدل، وابستگی مشاهدات، سوگیری انتخاب و گمشدگی می‌توانند تفسیر را محدود کنند.']),
 ('چندآزمونی و یافته منفی',['پیامد اصلی و تحلیل تأییدی را از تحلیل‌های اکتشافی جدا کنید. اگر آزمون‌های متعدد انجام می‌دهید، راه کنترل خطا یا منطق گزارش را توضیح دهید. نتیجه غیرمعنی‌دار به‌تنهایی هم‌ارزی یا نبود اثر را اثبات نمی‌کند؛ آزمون هم‌ارزی و طراحی آن پرسش دیگری است.']),
 ('الگوی گزارش آموزشی',['«اختلاف برآوردشده = [مقدار و واحد]؛ فاصله اطمینان = [حد پایین، حد بالا]؛ روش = [مدل و تنظیم‌ها]؛ محدودیت اصلی = [محدودیت].» این قالب نتیجه واقعی نیست. جدول نمونه تحلیلی و حساسیت برآورد به تصمیم‌های مهم را نیز اضافه کنید؛ عدد بدون بافت، گزارش کامل محسوب نمی‌شود.'])],['اثر و جهت و واحد روشن‌اند.','فاصله اطمینان و روش آن آمده‌اند.','همه تحلیل‌های اصلی گزارش شده‌اند.','نتیجه‌گیری از طراحی و شواهد فراتر نمی‌رود.']),
('Effect sizes, confidence intervals and p-values','Report magnitude, direction, units and uncertainty alongside significance tests; separate exploratory analyses and avoid treating nonsignificance as proof of no effect.',[
 ('Keep the substantive question visible',['Describe how large a difference or association is and what it means for the research question. Report original units, relevant populations and timeframes. Standardized effects can help comparison but may obscure the meaning of the original scale.']),
 ('Understand what a p-value does not establish',['The ASA statement warns against interpreting a p-value alone as the probability that the null hypothesis is true, effect magnitude or scientific importance. Do not reduce research decisions to a threshold. Sample size and design influence the evidence.']),
 ('Report uncertainty and assumptions',['Present the estimate, interval and calculation method. Frequentist coverage concerns the procedure’s repeated-sampling behavior, rather than a probability assigned to a fixed parameter after the interval is observed. Model assumptions, dependence, selection bias and missingness can limit interpretation.']),
 ('Address multiple analyses',['Separate primary confirmatory outcomes from exploratory analyses and explain multiplicity handling. A nonsignificant finding alone demonstrates neither equivalence nor absence of an effect. Equivalence requires its own question, margin and suitable design.']),
 ('A transparent reporting template',['Teaching template: estimated difference [value and units], interval [lower, upper], method [model and settings], key limitation [limitation]. These placeholders are not actual results. Add the analytical sample and sensitivity to important decisions; an isolated number is insufficient.'])],['State effect, direction and units.','Report the interval and method.','Include all primary analyses.','Keep conclusions within design and evidence.']),
('حجم الأثر وفترات الثقة وقيمة p؛ تقرير مسؤول','اعرض مقدار الأثر واتجاهه ووحدته وعدم اليقين إلى جانب اختبارات الدلالة، ولا تساوِ غياب الدلالة بإثبات غياب الأثر.',[
 ('السؤال العلمي قبل العتبة',['وضّح مقدار الفرق أو العلاقة ومعناه للسؤال، مع الوحدة الأصلية والسكان والزمن. يفيد الأثر المعياري في المقارنة لكنه قد يحجب معنى المقياس الأصلي.']),
 ('حدود قيمة p',['يحذّر بيان ASA من تفسير قيمة p وحدها كاحتمال صحة الفرضية الصفرية أو مقدار الأثر أو أهميته العلمية. لا تختزل القرار في عتبة؛ يؤثر حجم العينة والتصميم في قوة الأدلة.']),
 ('عدم اليقين والافتراضات',['اعرض التقدير والفترة وطريقة حسابها. في التفسير التكراري تتعلق التغطية بسلوك الإجراء في أخذ عينات متكرر، لا باحتمال لمعلم ثابت بعد مشاهدة الفترة. تؤثر افتراضات النموذج واعتماد الملاحظات والتحيز والقيم المفقودة في التفسير.']),
 ('الاختبارات المتعددة والنتائج غير الدالة',['افصل النتائج التأكيدية الأساسية من التحليلات الاستكشافية ووضّح معالجة التعدد. لا تثبت نتيجة غير دالة التكافؤ أو غياب الأثر؛ يتطلب التكافؤ سؤالاً وهامشاً وتصميماً مناسباً.']),
 ('قالب تقرير شفاف',['قالب تعليمي: الفرق المقدر [قيمة ووحدة]، الفترة [حد أدنى وأعلى]، الطريقة [نموذج وإعدادات]، القيد [القيد الأساسي]. ليست هذه نتائج حقيقية. أضف العينة التحليلية وحساسية التقدير للقرارات المهمة؛ لا يكفي رقم منفرد.'])],['وضوح الأثر والاتجاه والوحدة.','ذكر الفترة وطريقتها.','عرض جميع التحليلات الأساسية.','التزام الاستنتاج بحدود الأدلة.']))

add('missing-data','analysis','data-analysis','data-analysis',['research-data','effect-size-uncertainty','preregistration'],['mice','cornell','asa'],
('داده گمشده و تحلیل حساسیت؛ از تشخیص تا گزارش','الگوی گمشدگی، دلایل احتمالی، فرض‌های MCAR و MAR و MNAR و گزینه‌های تحلیل را بررسی کنید؛ تصمیم‌ها و حساسیت نتایج را شفاف گزارش دهید.',[
 ('گمشدگی را قبل از تحلیل بشناسید',['برای هر متغیر و گروه، تعداد و نسبت مقادیر گمشده و هم‌زمانی آن‌ها را بررسی کنید. مقدار صفر، پاسخ «نمی‌دانم»، عدم کاربرد و خطای ثبت را یک کد واحد نگذارید. علت شناخته‌شده را جدا ثبت کنید و فرایند گردآوری را برای جلوگیری از گمشدگی قابل پیشگیری اصلاح کنید.']),
 ('فرض‌ها را با قطعیت اشتباه نگیرید',['MCAR، MAR و MNAR درباره رابطه گمشدگی با داده‌های مشاهده‌شده و مشاهده‌نشده‌اند. مشاهده یک الگو یا انجام یک آزمون، تمام این فرض‌ها را اثبات نمی‌کند. دانش موضوعی، روش جمع‌آوری و تحلیل حساسیت برای دفاع از انتخاب روش لازم‌اند.']),
 ('حذف کامل و جای‌گذاری ساده',['حذف تمام موارد ناقص می‌تواند نمونه و جمعیت قابل تحلیل را تغییر دهد و تحت بعضی سازوکارها سوگیری ایجاد کند. جای‌گذاری همه مقادیر با میانگین، معمولاً ساختار واریانس و رابطه‌ها را مخدوش می‌کند و نباید پیش‌فرض خودکار باشد. انتخاب روش باید با هدف، مدل و طراحی سازگار باشد.']),
 ('جای‌گذاری چندگانه',['بسته mice در R چند مجموعه داده جای‌گذاری‌شده می‌سازد؛ تحلیل و ترکیب نتایج باید طبق روش مناسب انجام شوند. مدل جای‌گذاری، نوع متغیر، ساختار زمانی یا خوشه‌ای و متغیرهای کمکی را بررسی کنید. همگرایی و معقول‌بودن داده‌های ساخته‌شده را کنترل کنید؛ داده جای‌گذاری‌شده را داده واقعی اندازه‌گیری‌شده معرفی نکنید.']),
 ('ثبت تصمیم و حساسیت',['تعداد نمونه قبل و بعد از هر تصمیم، الگوی گمشدگی، فرض‌ها، روش، تنظیم‌ها و مقایسه سناریوهای معقول را گزارش کنید. اگر نتیجه با تصمیم متفاوت به‌طور مهم تغییر می‌کند، این وابستگی را در بحث بیاورید. نسبت گمشدگی به‌تنهایی یک آستانه جهانی برای انتخاب روش نمی‌دهد.'])],['کدهای گمشدگی از صفر و عدم کاربرد جدا هستند.','فرض‌ها و روش توجیه شده‌اند.','فرایند تحلیل و ترکیب نتایج مستند است.','حساسیت نتیجه و تغییر نمونه گزارش شده‌اند.']),
('Missing data and sensitivity analysis','Inspect missingness patterns, distinguish assumptions from evidence and justify complete-case or imputation methods; report analytical samples and sensitivity transparently.',[
 ('Describe the pattern first',['Summarize missing values by variable and group. Distinguish zero, unknown, not applicable and recording failures. Preserve known reasons and improve collection where missingness is preventable.']),
 ('Treat mechanisms as assumptions',['MCAR, MAR and MNAR concern relationships between missingness and observed or unobserved information. A pattern or test cannot establish all these assumptions. Use subject knowledge, collection procedures and sensitivity analyses.']),
 ('Avoid automatic deletion or mean replacement',['Complete-case analysis changes the analytical sample and may be biased under some mechanisms. Mean replacement commonly distorts variability and relationships. Neither should be selected by default without checking design and analytical goals.']),
 ('Multiple imputation requires a full workflow',['The R package mice creates multiple imputed datasets; analyze and pool them appropriately. Check variable types, temporal or clustered structure, auxiliary information, diagnostics and plausible imputed values. Do not present imputed values as actually measured observations.']),
 ('Report decisions and their consequences',['Document sample changes, patterns, assumptions, methods and settings; compare plausible alternatives. Explain material dependence of conclusions on these decisions. A missingness percentage alone does not provide a universal rule for selecting the method.'])],['Separate missing codes from zero and inapplicability.','Justify mechanisms and methods.','Document analysis and pooling.','Report sample changes and sensitivity.']),
('القيم المفقودة وتحليل الحساسية','افحص أنماط الفقد وافتراضاته، وبرّر الاستبعاد أو التعويض، ووثّق العينات التحليلية وحساسية الاستنتاج للقرارات المختلفة.',[
 ('وصف النمط أولاً',['لخّص الفقد حسب المتغير والمجموعة. افصل الصفر وعدم المعرفة وعدم انطباق السؤال وأخطاء التسجيل. احفظ الأسباب المعروفة وحسّن الجمع حيث يمكن منع الفقد.']),
 ('الآليات افتراضات وليست يقيناً',['تتعلق MCAR وMAR وMNAR بعلاقة الفقد بالمعلومات المشاهدة وغير المشاهدة. لا يثبت نمط أو اختبار جميع هذه الافتراضات. استخدم المعرفة الموضوعية وإجراءات الجمع وتحليل الحساسية.']),
 ('تجنب القرارات الآلية',['يغيّر تحليل الحالات الكاملة العينة وقد يسبب تحيزاً في بعض الآليات. يشوّه التعويض بالمتوسط التباين والعلاقات غالباً. لا تختَر أيهما تلقائياً دون مراجعة التصميم والهدف.']),
 ('التعويض المتعدد مسار كامل',['ينشئ mice في R مجموعات بيانات معوّضة متعددة تتطلب التحليل والتجميع بطريقة مناسبة. افحص أنواع المتغيرات والبنية الزمنية أو العنقودية والمعلومات المساعدة والتشخيص ومعقولية القيم. لا تنسب القيم المعوّضة إلى قياسات فعلية.']),
 ('التوثيق والحساسية',['وثّق تغير العينة والنمط والافتراضات والطريقة والإعدادات، وقارن بدائل معقولة. اشرح اعتماد الاستنتاج على هذه القرارات إذا كان جوهرياً. نسبة الفقد وحدها لا تحدد قاعدة عامة لاختيار الطريقة.'])],['فصل رموز الفقد عن الصفر.','تبرير الافتراضات والطريقة.','توثيق التحليل وتجميع النتائج.','عرض تغير العينة والحساسية.']))

add('qualitative-research','design','team','scientific-writing',['research-design','survey-design','reporting-guidelines'],['coreq','equator','casp'],
('پژوهش کیفی؛ مصاحبه، کدگذاری و مسیر تفسیر','پرسش کیفی، نمونه‌گیری هدفمند، مصاحبه، بازاندیشی پژوهشگر و تحلیل مستند را طراحی کنید؛ گزارش را با راهنمای متناسب با روش مرور کنید.',[
 ('روش را با پرسش پیوند دهید',['پژوهش کیفی برای فهم معنا، تجربه و فرایند مفید است، اما هر پرسش کیفی یک روش واحد ندارد. رویکرد معرفت‌شناختی و روش تحلیل را توضیح دهید. تحلیل مضمون، نظریه زمینه‌ای و پدیدارشناسی تعهدهای متفاوتی دارند؛ نام روش را صرفاً به‌عنوان برچسب اضافه نکنید.']),
 ('نمونه‌گیری و رابطه پژوهشگر',['منطق انتخاب افراد یا موقعیت‌ها و محدودیت دسترسی را بنویسید. تعداد مصاحبه یک رقم ثابت جهانی نیست. نقش، پیش‌فرض‌ها و رابطه پژوهشگر با مشارکت‌کنندگان بر داده و تفسیر اثر می‌گذارد؛ یادداشت بازاندیشی و تصمیم‌های جذب را نگه دارید.']),
 ('مصاحبه و حفاظت از بافت',['راهنمای نیمه‌ساختاریافته را با پرسش‌های باز و پیگیری‌های روشن آزمون کنید. برای ضبط، استفاده از نقل‌قول و نحوه نگهداری داده توافق مناسب لازم است. در پیاده‌سازی و ترجمه، تغییرهای مؤثر بر معنا و حذف مشخصات قابل شناسایی را ثبت کنید.']),
 ('از کد تا تفسیر',['کدها، نمونه متن، یادداشت تحلیلی و تغییر دسته‌ها را به هم متصل کنید تا خواننده مسیر استدلال را بفهمد. استفاده از نرم‌افزاری مانند NVivo خودِ تحلیل یا اعتبار آن نیست. توافق بین کدگذاران یا اشباع را فقط زمانی به کار ببرید که با رویکرد شما سازگار و تعریف آن روشن باشد.']),
 ('گزارش و محدودیت',['COREQ برای مصاحبه و گروه کانونی راهنمای گزارش‌دهی است؛ برای روش‌های دیگر راهنمای مناسب را جست‌وجو کنید. نقل‌قول‌ها باید شواهد تفسیر باشند و حریم خصوصی را حفظ کنند. موارد ناسازگار و تفسیر جایگزین را بررسی کنید و ادعای تعمیم آماری را به‌طور خودکار از نمونه هدفمند نتیجه نگیرید.'])],['رویکرد و روش تحلیل روشن‌اند.','انتخاب نمونه و نقش پژوهشگر توضیح دارند.','کد، شاهد و تفسیر قابل پیگیری‌اند.','راهنمای گزارش با نوع مطالعه تناسب دارد.']),
('Qualitative research: interviews, coding and interpretation','Connect qualitative questions to sampling, researcher reflexivity and documented interpretation; choose reporting guidance that fits the specific methodology.',[
 ('Choose a coherent approach',['Qualitative work investigates meaning, experience and processes, but not through one universal method. Explain the epistemological position and analytical approach. Thematic analysis, grounded theory and phenomenology carry different commitments.']),
 ('Explain sampling and positionality',['Document why people or settings were selected and describe access limitations. Interview counts are not governed by a universal number. Preserve reflexive notes about researcher assumptions and relationships with participants.']),
 ('Preserve context in collection',['Pilot open questions and follow-up prompts. Establish appropriate arrangements for recording, quotations and retention. Document transcription and translation choices that affect meaning and remove identifying details appropriately.']),
 ('Make interpretation traceable',['Connect codes, extracts, analytical notes and category revisions. Software organizes materials but does not establish the validity of an interpretation. Use coder agreement or saturation only when coherent with the chosen approach and clearly defined.']),
 ('Report within methodological limits',['COREQ addresses reporting interviews and focus groups; other methods may need other guidance. Quotations should support interpretation and respect privacy. Examine contradictory cases and alternatives, and do not infer statistical generalizability automatically from purposive sampling.'])],['Explain the methodological approach.','Document sampling and researcher role.','Connect codes, evidence and interpretations.','Use appropriate reporting guidance.']),
('البحث النوعي؛ المقابلات والترميز ومسار التفسير','اربط السؤال النوعي باختيار المشاركين وانعكاسية الباحث وتحليل موثق، واختر إرشادات التقرير الملائمة للمنهجية المستخدمة.',[
 ('منهج متسق مع السؤال',['يدرس البحث النوعي المعنى والخبرة والعمليات، لكن لا توجد طريقة واحدة لجميع الأسئلة. فسّر الموقف المعرفي وطريقة التحليل؛ للتحليل الموضوعي والنظرية المجذرة والظاهراتية التزامات مختلفة.']),
 ('العينة وموقع الباحث',['وثّق منطق اختيار الأشخاص والمواقع وقيود الوصول. لا يحكم عدد المقابلات رقم عالمي ثابت. احفظ ملاحظات انعكاسية عن افتراضات الباحث وعلاقته بالمشاركين.']),
 ('حفظ السياق أثناء الجمع',['اختبر الأسئلة المفتوحة والمتابعات. اتفق على التسجيل واستخدام الاقتباسات والاحتفاظ بالبيانات. وثّق قرارات التفريغ والترجمة المؤثرة في المعنى، واحذف تفاصيل التعريف بطريقة مناسبة.']),
 ('تفسير قابل للتتبع',['اربط الرموز بالمقتطفات والملاحظات التحليلية وتعديلات الفئات. ينظم البرنامج المواد لكنه لا يثبت صحة التفسير. استخدم اتفاق المرمزين أو التشبع فقط عندما يتسق مع المنهج ويكون تعريفه واضحاً.']),
 ('التقرير ضمن حدود المنهج',['يتناول COREQ المقابلات والمجموعات البؤرية وقد تتطلب طرق أخرى إرشادات مختلفة. تدعم الاقتباسات التفسير مع احترام الخصوصية. افحص الحالات المخالفة والتفسيرات البديلة ولا تستنتج تعميماً إحصائياً تلقائياً من عينة قصدية.'])],['توضيح المنهجية.','توثيق العينة ودور الباحث.','ربط الرمز بالدليل والتفسير.','اختيار إرشادات مناسبة.']))

add('survey-design','design','proposal','proposal',['research-design','qualitative-research','sample-size-power'],['pew','casp'],
('طراحی پرسش‌نامه؛ سنجش، پایلوت و کیفیت پاسخ','از مفهوم تا سؤال و مقیاس پاسخ حرکت کنید؛ سوگیری واژگان، ترتیب، بار پاسخ و سازگاری ترجمه را با اجرای مقدماتی و مستندسازی بررسی کنید.',[
 ('ابتدا مفهوم و کاربرد',['قبل از نوشتن سؤال، مشخص کنید کدام سازه یا رفتار و در چه بازه زمانی سنجیده می‌شود و پاسخ قرار است در چه تحلیلی استفاده شود. استفاده از ابزار موجود نیازمند بررسی تناسب، مجوز و شواهد روان‌سنجی مرتبط است؛ پرسش‌نامه طولانی‌تر لزوماً بهتر نیست.']),
 ('واژگان و گزینه‌ها',['یک سؤال را به دو موضوع مستقل تبدیل نکنید؛ سؤال «استاد و امکانات را چگونه ارزیابی می‌کنید؟» برای تفسیر جداگانه مناسب نیست. از واژگان هدایت‌کننده، فرض نادرست و اصطلاح نامفهوم پرهیز کنید. گزینه‌ها باید با مفهوم، حافظه پاسخ‌دهنده و نحوه تحلیل تناسب داشته باشند.']),
 ('ترتیب و محیط پاسخ',['ترتیب سؤال‌ها و گزینه‌ها، شیوه ارائه و نوع تماس می‌تواند پاسخ را تغییر دهد. جابه‌جایی تصادفی فقط برای گزینه‌هایی مناسب است که ترتیب معنایی ضروری ندارند. نسخه موبایل، زمان تکمیل، شاخه‌بندی و امکان انصراف را بررسی کنید.']),
 ('آزمون شناختی و پایلوت',['در یک بررسی مقدماتی، از افراد بخواهید توضیح دهند سؤال را چگونه فهمیده‌اند و پاسخ را چگونه انتخاب می‌کنند. این بررسی با یک اجرای کوچک برای کنترل مدت، گمشدگی و خطای سامانه مکمل است. برای ابزار چندزبانه، هم‌ارزی معنایی را با متخصص و کاربران بررسی کنید؛ ترجمه معکوس به‌تنهایی تمام مسائل فرهنگی را حل نمی‌کند.']),
 ('نسخه نهایی و گزارش',['متن سؤال و گزینه‌ها، ترتیب، تاریخ نسخه، دستورالعمل، منطق شاخه‌بندی و تغییرهای پایلوت را حفظ کنید. نرخ پاسخ را با تعریف صورت و مخرج گزارش کنید و نمونه در دسترس را نمونه نماینده همه دانشجویان معرفی نکنید. جدول مفاهیم، سؤال‌ها و تحلیل هدف، خروجی عملی این مرحله است.'])],['هر سؤال یک هدف قابل توضیح دارد.','بازه زمانی و گزینه‌ها روشن‌اند.','پایلوت و بازبینی ترجمه ثبت شده‌اند.','نسخه اجراشده و منطق شاخه‌بندی محفوظ‌اند.']),
('Survey design: questions, piloting and response quality','Translate constructs into clear questions and answer scales; test wording, order, burden and language equivalence before running the final questionnaire.',[
 ('Define constructs and use',['Specify the construct or behavior, timeframe and intended analysis. Existing instruments need appropriate permissions and relevant measurement evidence. A longer questionnaire is not necessarily a better one.']),
 ('Avoid ambiguous wording',['Ask one interpretable question at a time. Combining instructor quality and facilities in one item prevents separate interpretation. Avoid leading terms, unsupported assumptions and unfamiliar jargon. Match answer options to the concept and respondent recall.']),
 ('Review order and administration',['Question order, mode and option presentation can influence responses. Randomization is not suitable for every naturally ordered scale. Test mobile display, completion time, branching and withdrawal.']),
 ('Use cognitive testing and a pilot',['Ask potential respondents how they interpret items and choose answers. Complement this with a small workflow pilot for missingness, timing and interface errors. Assess semantic and cultural equivalence in multilingual instruments; back-translation alone is not sufficient.']),
 ('Preserve the actual questionnaire',['Keep wording, options, order, version date, instructions, branching and pilot changes. Define response-rate denominators and do not describe a convenience sample as representative of all students. Deliver a construct-to-item-to-analysis mapping.'])],['Give each item an explicit purpose.','Clarify timeframes and options.','Document pilots and translation review.','Preserve the administered version.']),
('تصميم الاستبيان؛ الأسئلة والتجريب وجودة الإجابات','حوّل المفاهيم إلى أسئلة ومقاييس واضحة، واختبر الصياغة والترتيب والعبء وتكافؤ اللغات قبل تنفيذ الاستبيان النهائي.',[
 ('المفهوم والاستخدام',['حدّد البناء أو السلوك والزمن والتحليل المقصود. تتطلب الأدوات الموجودة إذناً مناسباً ودليلاً قياسياً ذا صلة. الاستبيان الأطول ليس أفضل تلقائياً.']),
 ('صياغة قابلة للتفسير',['اسأل عن موضوع واحد في كل بند؛ جمع جودة المدرس والتجهيزات في سؤال يمنع تفسيرهما منفصلين. تجنب التوجيه والافتراضات غير المدعومة والمصطلحات المجهولة، ووائم الخيارات مع المفهوم وقدرة التذكر.']),
 ('الترتيب وطريقة التطبيق',['قد يؤثر ترتيب البنود وطريقة الاتصال وعرض الخيارات في الإجابات. لا تلائم العشوائية كل مقياس ذي ترتيب طبيعي. اختبر الهاتف والمدة والتفرعات وإمكان الانسحاب.']),
 ('اختبار الفهم والتنفيذ التجريبي',['اسأل مشاركين محتملين كيف فهموا البنود واختاروا الإجابات، ثم اختبر مسار التنفيذ لرصد الفقد والوقت وأخطاء الواجهة. افحص التكافؤ الدلالي والثقافي بين اللغات؛ الترجمة العكسية وحدها غير كافية.']),
 ('حفظ النسخة المنفذة',['احفظ النص والخيارات والترتيب والتاريخ والتعليمات والتفرعات وتعديلات التجريب. عرّف مقام معدل الاستجابة ولا تنسب التمثيل العام لعينة متاحة. سلّم جدولاً يربط المفهوم بالبند والتحليل.'])],['هدف واضح لكل بند.','وضوح الزمن والخيارات.','توثيق التجريب ومراجعة الترجمة.','حفظ نسخة التطبيق.']))

add('causal-inference','analysis','data-analysis','data-analysis',['research-design','effect-size-uncertainty','missing-data'],['causal','casp'],
('همبستگی و استنباط علّی؛ سؤال، فرض‌ها و سوگیری','بین رابطه، پیش‌بینی و اثر علّی تفاوت بگذارید؛ مداخله هدف، ترتیب زمانی، مخدوش‌گرها و فرض‌های شناسایی را پیش از مدل‌سازی توضیح دهید.',[
 ('اثرِ چه مداخله‌ای برای چه جمعیتی؟',['عبارت «X بر Y اثر دارد» بدون تعریف مداخله، جمعیت و زمان کافی نیست. مشخص کنید کدام شرایط را مقایسه می‌کنید و پیامد در چه زمانی اندازه‌گیری می‌شود. برای مثال آموزشی، «رابطه حضور در کلاس با نمره» با «اثر یک برنامه حضور مشخص بر نمره» سؤال یکسانی نیست.']),
 ('طرح، زمان و متغیرها',['ترتیب زمانی مواجهه، متغیرها و پیامد را بنویسید. مخدوش‌گر، میانجی و متغیر حاصل از انتخاب نقش یکسان ندارند. تنظیم همه متغیرهای موجود در رگرسیون می‌تواند سوگیری جدید ایجاد کند؛ انتخاب متغیر باید با دانش موضوعی و فرض‌های روشن پشتیبانی شود.']),
 ('نمودار و فرض‌های شناسایی',['نمودار علّی می‌تواند فرض‌های رابطه‌ها و مسیرهای سوگیری را قابل بررسی کند، اما خودِ نمودار واقعیت را ثابت نمی‌کند. نبود مخدوش‌گری اندازه‌گیری‌نشده، سازگاری تعریف مداخله و امکان مقایسه گروه‌ها باید در روش مناسب بررسی شوند. بخشی از این فرض‌ها از داده به‌تنهایی قابل اثبات نیستند.']),
 ('داده مشاهده‌ای و آزمایش',['تصادفی‌سازی با اجرای درست به کنترل بعضی منابع مخدوش‌گری کمک می‌کند؛ ریزش، عدم پایبندی و اندازه‌گیری همچنان اهمیت دارند. تحلیل مشاهده‌ای به طراحی و فرض‌های دفاع‌پذیر نیاز دارد. ضریب معنادار یا دقت پیش‌بینی بالا به‌تنهایی شاهد کافی برای علیت نیست.']),
 ('گزارش و تحلیل حساسیت',['هدف، روش شناسایی، متغیرهای تنظیم‌شده و دلیل انتخاب، محدودیت‌ها و حساسیت به فرض‌ها را گزارش کنید. اگر طراحی فقط رابطه را پشتیبانی می‌کند، در عنوان و بحث زبان علّی قطعی به کار نبرید. آموزش این مبحث جای بازبینی تخصصی طراحی واقعی را نمی‌گیرد.'])],['مداخله، جمعیت و زمان روشن‌اند.','نقش متغیرها با دانش موضوعی تعیین شده است.','فرض‌های شناسایی و سوگیری‌ها اعلام شده‌اند.','زبان نتیجه با قدرت طراحی هماهنگ است.']),
('Association and causal inference: questions and assumptions','Separate association, prediction and causal effects; define the intervention, timing, confounders and identification assumptions before interpreting a model causally.',[
 ('Define a meaningful contrast',['Specify the intervention, population, comparison and outcome time. An association between attendance and grades differs from the effect of a defined attendance program. Without a clear contrast, a claim that X affects Y is underspecified.']),
 ('Consider time and variable roles',['Record when exposure, covariates and outcomes occur. Confounders, mediators and selection variables have different roles. Adjusting for every available variable may introduce bias; justify the set using subject knowledge and explicit assumptions.']),
 ('Make assumptions reviewable',['Causal diagrams can expose assumptions and bias paths but cannot establish that those assumptions are true. Appropriate methods require attention to exchangeability, intervention consistency and comparison support. Some identifying assumptions cannot be verified from the observed dataset alone.']),
 ('Design matters more than a coefficient',['Randomization helps control some confounding when implemented appropriately; attrition, adherence and measurement still matter. Observational inference needs a defensible design and assumptions. Significance or predictive accuracy alone is insufficient for a causal claim.']),
 ('Report limitations and sensitivity',['Describe the target effect, identification strategy, adjustment choices and sensitivity to assumptions. Use association language when the design supports only association. Educational guidance cannot substitute for specialist review of the actual study.'])],['Define intervention, population and timing.','Justify covariate roles.','Disclose identification assumptions and bias.','Match claims to the design.']),
('الارتباط والاستدلال السببي؛ السؤال والافتراضات','ميّز الارتباط والتنبؤ والأثر السببي، وحدّد التدخل والتوقيت والمربكات وافتراضات التعرف قبل تفسير النموذج سببياً.',[
 ('مقارنة محددة المعنى',['حدّد التدخل والسكان والمقارنة ووقت النتيجة. علاقة الحضور بالدرجات تختلف عن أثر برنامج حضور محدد. ادعاء تأثير X في Y دون هذه التفاصيل غير مكتمل.']),
 ('الزمن وأدوار المتغيرات',['وثّق توقيت التعرض والمتغيرات والنتائج. للمربكات والوسطاء ومتغيرات الاختيار أدوار مختلفة. قد يخلق ضبط كل المتغيرات المتاحة تحيزاً؛ برّر المجموعة بمعرفة موضوعية وافتراضات صريحة.']),
 ('افتراضات قابلة للمراجعة',['تكشف الرسوم السببية الافتراضات ومسارات التحيز لكنها لا تثبت صحتها. تتطلب الطريقة المناسبة مراعاة قابلية المقارنة واتساق التدخل وتوفر المقارنات. لا يمكن التحقق من بعض افتراضات التعرف بالبيانات المشاهدة وحدها.']),
 ('التصميم أساس التفسير',['تساعد العشوائية الصحيحة على ضبط بعض المربكات، مع بقاء الانسحاب والالتزام والقياس مهمين. يتطلب الاستدلال الرصدي تصميماً وافتراضات يمكن الدفاع عنها. الدلالة ودقة التنبؤ وحدهما لا تكفيان لإثبات السببية.']),
 ('الحدود والحساسية',['صف الأثر المستهدف واستراتيجية التعرف واختيار الضبط والحساسية للافتراضات. استخدم لغة الارتباط إذا كان التصميم يدعمه فقط. لا تستبدل الإرشادات التعليمية المراجعة المتخصصة للدراسة الفعلية.'])],['تعريف التدخل والسكان والتوقيت.','تبرير أدوار المتغيرات.','الإفصاح عن الافتراضات والتحيز.','توافق الادعاء مع التصميم.']))

add('reproducible-notebooks','data','programming','programming',['research-programming','research-data','fair-open-data'],['jupyter','readme','python','r'],
('دفترچۀ محاسباتی بازتولیدپذیر؛ Jupyter، R و محیط اجرا','کد، روایت، محیط و داده را برای اجرای دوباره سامان دهید؛ ترتیب اجرای سلول‌ها، وابستگی‌ها، مسیر فایل و ثبت خروجی‌ها را در پروژه علمی کنترل کنید.',[
 ('روایت علمی همراه با کد',['دفترچه محاسباتی باید توضیح دهد چرا هر مرحله انجام شده است، نه اینکه فقط خروجی نرم‌افزار را نمایش دهد. هدف، منشأ داده، تبدیل‌ها، فرض‌ها و تفسیر را کنار کد بنویسید. Jupyter کد و متن و خروجی را ترکیب می‌کند؛ گزارش در R نیز باید همین منطق قابل پیگیری را حفظ کند.']),
 ('خطر حالت پنهان',['اجرای سلول‌ها با ترتیب متفاوت می‌تواند متغیرهای قدیمی یا نتیجه وابسته به جلسه ایجاد کند. محیط را از نو شروع و همه مراحل را از ابتدا اجرا کنید. خروجی ذخیره‌شده ممکن است متعلق به نسخه قبلی کد باشد؛ یک اجرای تمیز برای فایل قابل انتشار لازم است.']),
 ('داده و محیط',['نسخه زبان و بسته‌ها، دستور ایجاد محیط، بذر تصادفی و مسیر ورودی را ثبت کنید. بذر ثابت به‌تنهایی تکرارپذیری روی همه سخت‌افزارها را تضمین نمی‌کند. داده مجاز یا نمونه آموزشی برچسب‌خورده و راه دریافت داده محدود را توضیح دهید؛ اطلاعات حساس و کلید دسترسی را وارد مخزن نکنید.']),
 ('ساختار و آزمون',['توابع قابل استفاده مجدد را از سلول‌های طولانی جدا کنید و برای مراحل حساس، کنترل دامنه، تعداد رکورد و پاسخ معلوم تعریف کنید. از مسیر نسبی و تنظیمات مستند استفاده کنید. فایل خام، داده پردازش‌شده و خروجی را جدا نگه دارید و نتیجه هر حذف یا تبدیل را ثبت کنید.']),
 ('بسته قابل تحویل',['README، دستور اجرا، محیط، داده نمونه یا مسیر دسترسی، دفترچه اجراشده و خروجی مورد انتظار را همراه کنید. یک همکار باید بتواند بدون پرسیدن مراحل پنهان، جریان اصلی را اجرا کند. فایل HTML یا PDF برای مطالعه مفید است ولی جای کد و محیط لازم برای بازاجرای تحلیل را نمی‌گیرد.'])],['اجرای تمیز از ابتدا موفق است.','نسخه‌ها و دستور محیط ثبت شده‌اند.','ورودی و خروجی و منشأ داده روشن‌اند.','README و کنترل‌های علمی همراه فایل‌اند.']),
('Reproducible notebooks: Jupyter, R and execution environments','Combine scientific explanation with code; control hidden state, dependencies, data paths and outputs so a colleague can rerun the analytical workflow.',[
 ('Write an analytical narrative',['Explain the purpose, data provenance, transformations, assumptions and interpretation alongside the code. Jupyter combines text, code and outputs; an R reporting workflow should preserve the same traceable reasoning.']),
 ('Eliminate hidden session state',['Out-of-order cells can reuse stale variables or session-dependent results. Restart the environment and run every step in order. Stored output may belong to an older code version, so prepare a clean execution before publishing.']),
 ('Record inputs and environment',['Document language and package versions, environment setup, random seeds and data locations. A fixed seed alone does not guarantee identical behavior across all hardware. Provide permitted data or clearly labeled teaching data and explain access restrictions. Keep credentials and confidential data out of repositories.']),
 ('Organize and check the workflow',['Move reusable logic into functions and add meaningful checks for ranges, record counts and known answers. Use documented relative paths. Separate raw data, processed data and outputs and preserve transformation decisions.']),
 ('Deliver a rerunnable package',['Include a README, execution command, environment description, sample or accessible inputs, executed notebook and expected outputs. A colleague should not need undocumented steps. HTML and PDF aid reading but do not replace the code and environment needed for rerunning.'])],['Complete a clean ordered run.','Record versions and setup.','Explain inputs, outputs and provenance.','Include documentation and scientific checks.']),
('دفاتر حسابية قابلة لإعادة التنفيذ؛ Jupyter وR والبيئة','اجمع الشرح العلمي والشفرة، واضبط حالة الجلسة والاعتماديات والمسارات والمخرجات كي يتمكن زميل من إعادة التحليل.',[
 ('رواية تحليلية مع الشفرة',['اشرح الهدف ومصدر البيانات والتحويلات والافتراضات والتفسير بجانب الكود. يجمع Jupyter النص والشفرة والمخرجات؛ ينبغي أن يحافظ تقرير R على الاستدلال القابل للتتبع نفسه.']),
 ('التخلص من حالة الجلسة الخفية',['قد يعيد تشغيل الخلايا خارج الترتيب استخدام متغيرات قديمة. أعد تشغيل البيئة ونفّذ كل الخطوات بالترتيب. قد تنتمي المخرجات المحفوظة لنسخة سابقة؛ جهّز تنفيذاً نظيفاً قبل النشر.']),
 ('المدخلات وبيئة التنفيذ',['وثّق نسخ اللغة والحزم وإنشاء البيئة والبذرة والمسارات. البذرة الثابتة وحدها لا تضمن التطابق على جميع الأجهزة. وفّر بيانات مسموحة أو بيانات تعليمية موضّحة وفسّر قيود الوصول. أبقِ المفاتيح والبيانات السرية خارج المستودع.']),
 ('التنظيم والفحص',['انقل المنطق المتكرر إلى دوال وأضف فحوصاً ذات معنى للمدى وعدد السجلات والإجابات المعروفة. استخدم مسارات نسبية موثقة وافصل الخام والمعالج والمخرجات واحفظ قرارات التحويل.']),
 ('حزمة قابلة لإعادة التشغيل',['ضمّن README وأمر التنفيذ والبيئة والمدخلات والمخرجات المتوقعة والدفتر المنفذ. يجب ألا يحتاج الزميل خطوات خفية. يساعد HTML وPDF القراءة لكنهما لا يستبدلان الشفرة والبيئة اللازمة للإعادة.'])],['تنفيذ نظيف بالترتيب.','توثيق النسخ والإعداد.','شرح المدخلات والمخرجات والمصدر.','إرفاق التوثيق والفحوص العلمية.']))

add('literature-search','search','library','proposal',['systematic-review','citation-styles','critical-appraisal'],['pubmed','harvard','prisma','zotero'],
('جست‌وجوی علمی بازتولیدپذیر؛ از کلیدواژه تا ثبت منابع','برای جست‌وجوی مقاله، پرسش را به مفاهیم تبدیل کنید؛ مترادف‌ها، منطق Boolean، پایگاه مناسب و دفتر جست‌وجوی قابل بازتولید را بسازید.',[
 ('پرسش را به بلوک‌های مفهومی تبدیل کنید',['پیش از جست‌وجو، مشخص کنید دقیقاً چه نوع شواهدی می‌خواهید: توصیف تجربه، برآورد یک رابطه، ارزیابی مداخله یا مقایسه روش‌ها. سپس دو یا سه مفهوم اصلی را جدا کنید. برای هر مفهوم، اصطلاح تخصصی، مترادف، املای متفاوت و واژه‌های محلی را بنویسید؛ ترجمه لفظی عنوان فارسی معمولاً کافی نیست.','مثال آموزشی: برای «یادگیری فعال و مشارکت دانشجویان»، یک بلوک برای روش آموزشی و یک بلوک برای مشارکت بسازید. جمعیت یا پیامد را فقط زمانی اضافه کنید که محدودکردن جست‌وجو شواهد مهم را حذف نکند. این مثال یک رشته جست‌وجوی اعتبارسنجی‌شده نیست.']),
 ('منطق جست‌وجو و واژگان کنترل‌شده',['در بسیاری از پایگاه‌ها OR مترادف‌ها را جمع و AND مفاهیم را ترکیب می‌کند؛ پرانتز و نقل‌قول رفتار جست‌وجو را تغییر می‌دهند. قواعد کوتاه‌سازی، جست‌وجوی عبارت و فیلدها بین سامانه‌ها متفاوت‌اند. راهنمای همان پایگاه را بخوانید؛ در PubMed، MeSH و نحوه نگاشت خودکار اصطلاح‌ها را بررسی کنید.']),
 ('چند مسیر برای کشف شواهد',['پایگاه را با رشته و نوع مدرک انتخاب کنید. فهرست دانشگاهی مانند HOLLIS به کشف کتاب و منابع متنوع کمک می‌کند؛ دسترسی به متن همه نتایج لزوماً آزاد نیست. جست‌وجوی استنادیِ منابع یک مقاله و مقالاتی که به آن استناد کرده‌اند می‌تواند مدارک جاافتاده را آشکار کند. پوشش یک موتور جست‌وجو معادل پوشش همه رشته‌ها نیست.']),
 ('دفتر جست‌وجو و مدیریت رکوردها',['نام پایگاه و رابط، تاریخ اجرا، رشته دقیق، محدودیت‌های زبان و سال و تعداد نتایج را ثبت کنید. فایل خروجی اولیه را نگه دارید و رکوردهای تکراری را با ترکیب DOI، عنوان و بررسی انسانی حذف کنید. برای مرور نظام‌مند، معیار غربال‌گری و علت حذف متن کامل را جدا ثبت کنید؛ تعداد نتایج متغیر است و یک جست‌وجوی قدیمی همیشه بازتولید عددیِ دقیق ندارد.']),
 ('کنترل کیفیت و تحویل',['راهبرد را با چند مقاله کلیدیِ مرتبط آزمون کنید: آیا آن‌ها پیدا می‌شوند؟ نتیجه‌های نامرتبط از کدام واژه آمده‌اند؟ در صورت نیاز از کتابدار متخصص بازبینی بگیرید. بسته نهایی شامل دفتر جست‌وجو، خروجی رکوردها، قواعد حذف تکرار و تاریخ به‌روزرسانی است؛ عبارت «جست‌وجوی کامل» بدون توضیح پوشش و محدودیت‌ها کافی نیست.'])],['پرسش و معیار ورود روشن است.','منطق جست‌وجو در هر پایگاه جدا آزموده شده است.','رکوردهای اولیه و نسخه جست‌وجو محفوظ‌اند.','نتایج جست‌وجو با ارزیابی کیفیت مطالعه اشتباه نشده‌اند.']),
('Reproducible literature searching: concepts, databases and logs','Build a research search using concepts, synonyms, Boolean logic and suitable databases; preserve a clear search log and manage records without losing provenance.',[
 ('Start with the evidence you need',['Specify whether the question concerns experiences, associations, interventions or methods. Split it into a few concepts and list synonyms, variant spellings and disciplinary terms. Translating a local-language title word for word rarely produces a sufficient search.','Teaching example: for active learning and student engagement, create a teaching-method block and an engagement block. Add population or outcome restrictions only after testing whether they remove relevant evidence. This example is not a validated search strategy.']),
 ('Translate the strategy for each database',['OR commonly combines synonyms and AND joins concepts, but phrase searching, truncation and field tags differ between interfaces. Consult the database’s own guide. In PubMed, review MeSH and automatic term mapping instead of assuming that an exact phrase and a mapped query behave identically.']),
 ('Use more than one discovery route',['Match the database to the discipline and document type. A library catalog such as HOLLIS can help discover books and other materials, but discovery does not grant access to every licensed item. Inspect references and forward citations of key studies. A broad search engine does not establish comprehensive disciplinary coverage.']),
 ('Preserve the search history',['Record database, interface, execution date, full query, limits and result count. Keep the original export; deduplicate with identifiers and title checks rather than an opaque deletion rule. For systematic reviews, also preserve screening decisions and reasons for full-text exclusions. A later rerun may produce different counts because database coverage changes.']),
 ('Test and deliver the strategy',['Check whether known relevant studies are retrieved and inspect where irrelevant results originate. A specialist librarian can help review the strategy. Deliver the search log, original records, deduplication rules and update date. Describe coverage and limitations instead of claiming an unexplained complete search.'])],['Define the question and eligibility rules.','Test syntax separately in every interface.','Preserve exports and query versions.','Keep discovery separate from study appraisal.']),
('البحث العلمي القابل لإعادة التنفيذ؛ الكلمات والقواعد والسجل','حوّل السؤال إلى مفاهيم ومترادفات، واختر قواعد البيانات المناسبة ووثّق استراتيجية البحث وإدارة المراجع دون فقدان مصدر السجلات.',[
 ('ابدأ بنوع الدليل المطلوب',['حدّد هل تبحث عن تجارب أو علاقة أو تدخل أو مقارنة طرق، ثم افصل المفاهيم الرئيسية واكتب المترادفات والمصطلحات التخصصية والتهجئات البديلة. ترجمة العنوان حرفياً لا تكفي لبناء استراتيجية جيدة.','مثال تعليمي: للتعلم النشط ومشاركة الطلبة، أنشئ مجموعة لمفهوم التدريس وأخرى للمشاركة. أضف حدود السكان والنتائج بعد اختبار أثرها على الاسترجاع؛ هذا المثال ليس استراتيجية بحث معتمدة.']),
 ('كيّف المنطق مع كل قاعدة',['تجمع OR المترادفات وتربط AND المفاهيم في كثير من الأنظمة، لكن البحث عن العبارات والاختصار والحقول يختلف بين الواجهات. اقرأ دليل القاعدة نفسها. في PubMed افحص MeSH وآلية تحويل المصطلحات تلقائياً ولا تفترض تطابق سلوك العبارة الحرفية مع البحث المفسّر.']),
 ('اجمع مسارات اكتشاف متعددة',['اختر القاعدة وفق التخصص ونوع الوثيقة. يساعد فهرس مثل HOLLIS على اكتشاف الكتب والمواد المتنوعة، لكن العثور على سجل لا يمنح حق قراءة جميع المواد المرخصة. افحص مراجع الدراسات الرئيسية والاستشهادات اللاحقة بها. لا يغطي محرك واحد جميع أنواع المعرفة.']),
 ('احفظ سجل البحث والقرارات',['وثّق القاعدة والواجهة والتاريخ والاستراتيجية الكاملة والقيود وعدد النتائج. احتفظ بالتصدير الأصلي وأزل التكرار بمعرّفات وعناوين ومراجعة بشرية. للمراجعة المنهجية، سجّل قرارات الفرز وأسباب استبعاد النصوص الكاملة. قد تتغير الأعداد عند إعادة البحث بسبب تحديث الفهرسة.']),
 ('اختبر الجودة قبل التسليم',['تحقق من ظهور دراسات معروفة الصلة وحدّد مصدر النتائج غير المناسبة. يمكن لأمين مكتبة متخصص مراجعة الاستراتيجية. سلّم سجل البحث والملفات الأصلية وقواعد إزالة التكرار وتاريخ التحديث؛ وصف التغطية والحدود أوضح من ادعاء بحث كامل بلا تفسير.'])],['السؤال ومعايير الأهلية واضحان.','اختُبرت الصياغة في كل واجهة.','حُفظت الملفات ونسخ الاستراتيجية.','اكتشاف الدراسات منفصل عن تقييم جودتها.']))

add('research-design','design','proposal','proposal',['research-proposal','causal-inference','sample-size-power'],['casp','equator','causal'],
('انتخاب طرح پژوهش؛ هماهنگی پرسش، داده و روش','طرح پژوهش را با هدف توصیفی، پیش‌بینی یا علّی هماهنگ کنید؛ متغیرها، واحد تحلیل، سوگیری‌ها و محدودیت‌های امکان‌سنجی را پیش از گردآوری داده ثبت کنید.',[
 ('سه هدف متفاوت',['«چه اتفاقی رخ می‌دهد؟»، «چه چیزی را می‌توان پیش‌بینی کرد؟» و «یک مداخله چه اثری دارد؟» پرسش‌های یکسانی نیستند. یک مدل پیش‌بینی دقیق لزوماً اثر علّی متغیرها را مشخص نمی‌کند. پیش از انتخاب نرم‌افزار، هدف و جمعیت مورد نظر و نوع نتیجه را بنویسید.']),
 ('طرح و واحد تحلیل',['داده مقطعی، طولی، آزمایشی، کیفی و آمیخته نیازهای متفاوتی دارند. مشخص کنید واحد تحلیل فرد، کلاس، سازمان، مصاحبه یا مشاهده تکراری است. چند مشاهده از یک شخص، چند فرد از یک خوشه و چند زمان از یک واحد را مستقل فرض نکنید؛ طرح نمونه‌گیری و مدل باید این وابستگی‌ها را در نظر بگیرند.']),
 ('عملیاتی‌کردن مفاهیم',['تعریف نظری سازه را از ابزار سنجش جدا کنید. برای هر متغیر، تعریف، زمان اندازه‌گیری، واحد، دامنه و نقش در مدل را ثبت کنید. پایایی بالا به‌تنهایی روایی سازه را اثبات نمی‌کند. استفاده از ابزار ترجمه‌شده به بررسی تناسب زبانی و فرهنگی نیاز دارد.']),
 ('امکان‌سنجی و سوگیری',['دسترسی واقعی به نمونه، زمان جذب، هزینه، مجوزها، توان محاسباتی و خطر ریزش را بررسی کنید. اگر داده در دسترس با جمعیت هدف تفاوت دارد، اثر این تفاوت را توضیح دهید. یک جدول خطر شامل مسئله، پیامد، راه کاهش و محدودیت باقی‌مانده بسازید.']),
 ('نمونه خروجی قابل دفاع',['یک جدول بسازید که هر پرسش را به داده لازم، روش گردآوری، تحلیل، فرض اصلی و خروجی وصل کند. اگر برای پرسشی داده یا روش معتبر ندارید، آن را بازنویسی کنید. قبل از مطالعه اصلی، اجرای آزمایشی فرایند می‌تواند ایرادهای ثبت داده و دستورالعمل را آشکار کند؛ مطالعه مقدماتی به‌تنهایی جای طراحی اصلی را نمی‌گیرد.'])],['هدف توصیفی، پیش‌بینی یا علّی مشخص است.','واحد تحلیل و وابستگی داده‌ها تعیین شده‌اند.','تعریف مفهومی با ابزار سنجش تطبیق دارد.','منابع، مجوزها و محدودیت‌ها ثبت شده‌اند.']),
('Choosing a research design: questions, data and methods','Align descriptive, predictive or causal aims with study design, measurement and the unit of analysis; document feasibility and bias before collecting data.',[
 ('Different questions require different evidence',['Describing a situation, predicting an outcome and estimating an intervention effect are different aims. A highly accurate predictor does not automatically identify causal effects. Write down the purpose, target population and outcome before choosing a statistical package.']),
 ('Specify the unit and dependencies',['Cross-sectional, longitudinal, experimental, qualitative and mixed-method designs have distinct requirements. State whether the unit is a person, class, organization, interview or repeated observation. Repeated measurements and clustered samples cannot simply be treated as independent observations; collection and analysis should respect these dependencies.']),
 ('Connect concepts to measurements',['Separate a theoretical construct from the instrument used to measure it. Document definitions, timing, units, ranges and model roles. Reliability alone does not establish construct validity. A translated instrument also needs appropriate linguistic and cultural assessment.']),
 ('Check feasibility and bias',['Review actual sample access, recruitment time, resources, permissions, computing needs and attrition. Describe differences between accessible participants and the target population. Maintain a risk table with the issue, consequence, mitigation and remaining limitation.']),
 ('Create a defensible design record',['Map each question to the required data, collection procedure, analysis, key assumption and output. Revise questions lacking suitable evidence or methods. A pilot can expose recording and workflow problems, but does not replace the main design. Include unresolved decisions so that a supervisor can review them before collection begins.'])],['Distinguish descriptive, predictive and causal goals.','Define the unit and dependencies.','Check construct and measurement alignment.','Document permissions, resources and limitations.']),
('اختيار تصميم البحث؛ اتساق السؤال والبيانات والمنهج','اربط الأهداف الوصفية والتنبؤية والسببية بالتصميم والقياس ووحدة التحليل، وسجّل الجدوى والتحيز قبل بدء جمع البيانات.',[
 ('حدّد وظيفة السؤال',['وصف الواقع والتنبؤ بالنتيجة وتقدير أثر تدخل أهداف مختلفة. لا يثبت نموذج تنبؤ دقيق التأثير السببي للمتغيرات. اكتب الهدف والسكان والنتيجة المطلوبة قبل اختيار البرنامج الإحصائي.']),
 ('التصميم ووحدة التحليل',['تختلف متطلبات الدراسات المقطعية والطولية والتجريبية والنوعية والمختلطة. حدّد هل الوحدة فرد أو صف أو مؤسسة أو مقابلة أو قياس متكرر. القياسات المتكررة والعينات العنقودية ليست ملاحظات مستقلة تلقائياً؛ ينبغي مراعاة الاعتماد في الجمع والتحليل.']),
 ('تحويل المفهوم إلى قياس',['افصل التعريف النظري عن أداة القياس، ووثّق تعريف كل متغير وتوقيته ووحدته ومداه ودوره. الثبات وحده لا يثبت صدق البناء. تتطلب الأداة المترجمة فحص ملاءمتها اللغوية والثقافية.']),
 ('الجدوى والتحيز',['راجع إمكان الوصول الفعلي للعينة ووقت الاستقطاب والموارد والتصاريح والحوسبة وخطر الانسحاب. اشرح الفرق بين العينة المتاحة والسكان المستهدفين. أنشئ جدول مخاطر يربط المشكلة بأثرها وإجراء الحد منها والقيود المتبقية.']),
 ('سجل تصميم قابل للمراجعة',['اربط كل سؤال بالبيانات المطلوبة وطريقة جمعها والتحليل والافتراض الأساسي والمخرج. عدّل السؤال الذي لا تتوفر له أدلة أو طريقة مناسبة. يكشف التنفيذ التجريبي مشكلات التسجيل وسير العمل، لكنه لا يستبدل التصميم الرئيسي. سجّل القرارات غير المحسومة لمراجعتها مع المشرف قبل التنفيذ.'])],['تمييز الوصف والتنبؤ والسببية.','تحديد الوحدة واعتماد الملاحظات.','تطابق المفهوم وأداة القياس.','توثيق التصاريح والموارد والقيود.']))

add('preregistration','design','proposal','proposal',['research-design','sample-size-power','research-data'],['prereg','prisma','dmp'],
('پیش‌ثبت پژوهش و برنامۀ تحلیل؛ فرضیه تا تصمیم‌های ازپیش‌تعیین‌شده','پرسش، پیامد اصلی، نمونه، قواعد حذف و تحلیل‌های تأییدی را پیش‌ثبت کنید؛ انحراف‌ها و تحلیل اکتشافی را با زمان و دلیل روشن گزارش دهید.',[
 ('پیش‌ثبت چه مسئله‌ای را حل می‌کند؟',['پیش‌ثبت، برنامه پژوهش را قبل از مرحله مرتبط با مشاهده نتایج ثبت می‌کند تا خواننده تصمیم‌های از پیش تعیین‌شده را از تصمیم‌های وابسته به داده تشخیص دهد. هدف، شفافیت است؛ ثبت یک برنامه ضعیف آن را به طراحی معتبر تبدیل نمی‌کند. تحلیل اکتشافی نیز ارزشمند است، به شرط اینکه با تحلیل تأییدی اشتباه معرفی نشود.']),
 ('چه چیزهایی را مشخص کنیم؟',['پرسش و فرضیه، پیامد اصلی، نحوه اندازه‌گیری، جمعیت و روش نمونه‌گیری، توجیه حجم نمونه، قاعده توقف، حذف موارد، مدیریت گمشدگی و مدل اصلی را بنویسید. در تحلیل چندپیامدی، منطق انتخاب آزمون‌ها و کنترل چندآزمونی را روشن کنید. عبارت مبهم «آزمون مناسب انجام می‌شود» تصمیم تحلیلی را مستند نمی‌کند.']),
 ('داده موجود و ثبت دیرهنگام',['اگر بخشی از داده یا نتایج را دیده‌اید، دقیقاً چه اطلاعاتی و در چه زمانی در دسترس بوده است را افشا کنید. برای داده ثانویه، مخفی‌بودن نتایج همیشه ممکن نیست. تاریخ ثبت را تغییر ندهید و برنامه پس از مشاهده نتایج را برنامه اولیه معرفی نکنید.']),
 ('تغییر برنامه و انتخاب سامانه',['اشکال طراحی، محدودیت گردآوری یا روش بهتر می‌تواند تغییر را ضروری کند. نسخه اولیه، زمان تغییر، دلیل و اثر آن را نگه دارید و تحلیل‌های افزوده را برچسب بزنید. سامانه ثبت را با رشته، سیاست دانشگاه یا نشریه و شرایط فعلی سرویس انتخاب کنید؛ ثبت مرور و کارآزمایی مسیرهای یکسانی ندارند.']),
 ('پروندۀ نهایی',['یک برنامۀ تحلیل خوانا، شناسه یا پیوند ثبت، نسخه‌های تغییر و جدول مقایسه «برنامه/اجرای واقعی» تحویل دهید. از الگوی قابل دریافت در جعبه‌ابزار شروع کنید و آن را با پروژه تنظیم کنید. پیش‌ثبت جای مجوز اخلاق، رضایت یا ثبت‌های الزامی خاص مطالعه را نمی‌گیرد.'])],['پیامد و تحلیل اصلی پیشاپیش مشخص‌اند.','دسترسی قبلی به داده اعلام شده است.','تغییرات همراه با زمان و دلیل محفوظ‌اند.','تحلیل‌های اکتشافی برچسب روشن دارند.']),
('Preregistration and analysis plans: decisions before results','Preregister questions, outcomes, sampling and confirmatory analyses; disclose prior data access, changes and exploratory work with a transparent decision record.',[
 ('Why record decisions in advance?',['Preregistration makes planned decisions distinguishable from choices informed by results. It supports transparency rather than certifying study quality. Exploratory work remains valuable when it is clearly identified instead of presented as a prespecified confirmation.']),
 ('Specify actionable details',['Include questions, hypotheses, primary outcomes, measurement, population, sampling, sample-size justification, stopping rules, exclusions, missing-data handling and the main model. Explain multiple-testing decisions when appropriate. Saying that a suitable test will be selected leaves the critical choice undocumented.']),
 ('Be candid about existing data',['For secondary data or a late registration, record which information and outcomes were already known and when they were accessed. Do not change the original date or describe a plan made after inspecting outcomes as the initial plan.']),
 ('Changes and registry selection',['A design problem or a better method may justify a change. Preserve the original version, date, rationale and implications; label additional analyses. Choose a registry appropriate to the discipline and institutional requirements, and check its current service conditions. Review protocols and trial registrations have different purposes.']),
 ('Prepare an auditable package',['Deliver the readable analysis plan, registration identifier, amendments and a planned-versus-executed table. Adapt the downloadable toolkit template to the study. Preregistration does not replace ethics review, consent or other mandatory study registration.'])],['Define primary outcomes and models in advance.','Disclose prior access to data.','Retain dated and justified amendments.','Label exploratory analyses clearly.']),
('التسجيل المسبق وخطة التحليل؛ القرارات قبل النتائج','سجّل الأسئلة والنتائج والعينة والتحليل التأكيدي مسبقاً، وأفصح عن الاطلاع السابق والتغييرات والتحليلات الاستكشافية بسجل قرارات واضح.',[
 ('لماذا نوثّق القرارات مبكراً؟',['يميّز التسجيل المسبق القرارات المخططة من الاختيارات المتأثرة بالنتائج. يدعم الشفافية ولا يمنح التصميم شهادة جودة. يظل التحليل الاستكشافي مهماً عندما يُقدَّم بصفته الاستكشافية ولا يُنسب إلى خطة تأكيدية سابقة.']),
 ('تفاصيل قابلة للتنفيذ',['اكتب السؤال والفرضية والنتيجة الأساسية والقياس والسكان والعينة وتبرير حجمها وقاعدة التوقف والاستبعاد ومعالجة القيم المفقودة والنموذج الأساسي. وضّح تعدد الاختبارات عند الحاجة؛ عبارة «اختبار مناسب» لا توثّق القرار التحليلي.']),
 ('البيانات الموجودة والتسجيل المتأخر',['في البيانات الثانوية أو التسجيل المتأخر، بيّن المعلومات والنتائج التي كانت معروفة ووقت الاطلاع عليها. لا تغيّر التاريخ ولا تسمِّ خطة وُضعت بعد رؤية النتائج خطة أولية.']),
 ('التعديلات واختيار السجل',['قد تستلزم مشكلة تصميم أو طريقة أفضل تغيير الخطة. احفظ النسخة الأصلية وتاريخ التعديل وسببه وأثره، وميّز التحليلات الجديدة. اختر سجلاً مناسباً للتخصص ومتطلبات المؤسسة، وافحص شروط الخدمة الحالية؛ تختلف وظيفة بروتوكول المراجعة عن تسجيل التجربة.']),
 ('حزمة نهائية قابلة للتدقيق',['قدّم خطة مفهومة ومعرّف التسجيل والتعديلات وجدولاً يقارن المخطط بالتنفيذ. عدّل قالب صندوق الأدوات وفق الدراسة. التسجيل المسبق لا يستبدل مراجعة الأخلاقيات أو الموافقة أو متطلبات تسجيل أخرى.'])],['تحديد النتيجة والنموذج مسبقاً.','الإفصاح عن الاطلاع السابق.','حفظ التعديلات وأسبابها وتواريخها.','تسمية التحليل الاستكشافي بوضوح.']))

add('sample-size-power','analysis','data-analysis','data-analysis',['research-design','preregistration','effect-size-uncertainty'],['ucla','asa'],
('حجم نمونه و توان آماری؛ توجیه به‌جای عدد ثابت','حجم نمونه را با طراحی، پیامد اصلی، اندازه اثر قابل توجیه، توان و دقت برآورد هماهنگ کنید؛ خوشه‌بندی، ریزش و تحلیل حساسیت را مستند کنید.',[
 ('یک فرمول برای همه پژوهش‌ها وجود ندارد',['برآورد نسبت، مقایسه میانگین، مدل رگرسیونی، مطالعه خوشه‌ای و تحلیل بقا نیازهای متفاوتی دارند. ابتدا پیامد و تحلیل اصلی را مشخص کنید. فرمولی مناسب برای یک پیمایش ساده را بدون بررسی برای مدل پیچیده یا مطالعه کیفی به کار نبرید.']),
 ('ورودی‌های قابل دفاع',['برای محاسبه مبتنی بر توان، خانواده آزمون، اندازه اثر هدف، سطح خطای نوع اول، توان، یک‌طرفه یا دوطرفه‌بودن و نسبت تخصیص را تعیین کنید. اندازه اثر را با شواهد پیشین، حداقل اثر مهم یا سناریوی علمی توجیه کنید؛ انتخاب مقدار صرفاً برای رسیدن به نمونه ارزان‌تر، توجیه علمی نیست.']),
 ('دقت برآورد و طراحی واقعی',['گاهی هدف اصلی، فاصله اطمینان با دقت معین است و نه عبور از آستانه معنی‌داری. خوشه‌بندی، سنجش تکراری، نمونه‌گیری پیچیده و داده نامتوازن می‌توانند نیاز به تحلیل یا شبیه‌سازی خاص ایجاد کنند. راهنماهای G*Power در UCLA مثال‌هایی برای آزمون‌های مشخص دارند؛ سازگاری آزمون انتخابی با طرح را جدا بررسی کنید.']),
 ('ریزش و حساسیت',['اگر به n مشاهده قابل تحلیل نیاز دارید و ریزش مورد انتظار r است، n/(1−r) فقط یک تقریب ساده برای جذب اولیه است؛ فرض آن را بنویسید و عدد را رو به بالا گرد کنید. برای چند اندازه اثر یا نرخ ریزش معقول، سناریو بسازید. بعد از نتیجه، «توان مشاهده‌شده» را جایگزین فاصله اطمینان یا طراحی اولیه نکنید.']),
 ('گزارش قابل بازبینی',['نام ابزار و نسخه، آزمون، تمام ورودی‌ها، منبع فرض‌ها و نتیجه هر سناریو را ثبت کنید. مثلاً به‌جای «نمونه ۱۰۰ نفر مناسب است»، توضیح دهید این تعداد تحت کدام فرض‌ها و برای کدام پیامد کافی برآورد شده است. این صفحه مقدار نهایی نمونه یک پروژه را تعیین نمی‌کند؛ طراحی و منابع پروژه باید بررسی شوند.'])],['آزمون با پرسش و طراحی سازگار است.','اندازه اثر و دقت توجیه شده‌اند.','خوشه‌بندی و ریزش بررسی شده‌اند.','فایل محاسبه و سناریوهای حساسیت محفوظ‌اند.']),
('Sample size and statistical power: a defensible justification','Justify sample size using the primary outcome, study design, plausible effect, power or precision; document attrition, clustering and sensitivity scenarios.',[
 ('Start with the primary analysis',['Estimating a proportion, comparing means, fitting regression, cluster sampling and survival analysis have different requirements. A formula for a simple survey is not automatically appropriate for a complex model or a qualitative study. Specify the main outcome and design first.']),
 ('Choose defensible assumptions',['A power calculation needs an appropriate test, target effect, type-I error level, power, sidedness and allocation assumptions. Justify the effect using prior evidence, a meaningful threshold or a scientific scenario. Choosing it only to obtain a cheaper sample is not a scientific rationale.']),
 ('Consider precision and design',['The goal may be a sufficiently precise interval rather than a significance threshold. Repeated measurements, clustering and imbalanced data can require specialist methods or simulation. UCLA’s G*Power examples address particular tests; verify the match to your design independently.']),
 ('Plan attrition and sensitivity',['For n analyzable observations and anticipated attrition r, n/(1−r) is a simple recruitment approximation under explicit assumptions; round upward. Compare plausible effect and attrition scenarios. After observing results, do not substitute observed power for interval estimates or the original design justification.']),
 ('Report enough to reproduce the calculation',['Preserve software and version, test, every input, supporting assumptions and scenario results. Explain for which outcome and assumptions a proposed sample is adequate rather than declaring a universal number. Final study planning requires review of the actual design and resources.'])],['Match the test to the research design.','Justify effect and precision.','Account for clustering and attrition.','Preserve inputs and sensitivity scenarios.']),
('حجم العينة والقوة الإحصائية؛ تبرير قابل للمراجعة','برّر حجم العينة بالنتيجة الأساسية والتصميم وحجم الأثر والقوة أو الدقة، ووثّق الانسحاب والتجمع وسيناريوهات الحساسية.',[
 ('ابدأ بالتحليل الأساسي',['تختلف متطلبات تقدير نسبة ومقارنة متوسطات والانحدار والعينة العنقودية وتحليل البقاء. لا تناسب معادلة مسح بسيط تلقائياً نموذجاً معقداً أو دراسة نوعية. حدّد النتيجة والتصميم أولاً.']),
 ('افتراضات يمكن الدفاع عنها',['يتطلب حساب القوة اختباراً مناسباً وحجم أثر ومستوى خطأ وقوة واتجاه الاختبار ونسبة تخصيص. برّر الأثر بدليل سابق أو حد مهم علمياً أو سيناريو منطقي. اختياره فقط لتقليل التكلفة ليس تبريراً علمياً.']),
 ('الدقة والتصميم الفعلي',['قد يكون الهدف فترة تقدير دقيقة بدلاً من تجاوز عتبة الدلالة. القياسات المتكررة والتجمع وعدم التوازن قد تستلزم طريقة متخصصة أو محاكاة. أمثلة G*Power لدى UCLA خاصة باختبارات محددة؛ افحص ملاءمتها للتصميم.']),
 ('الانسحاب والحساسية',['عند الحاجة إلى n ملاحظات قابلة للتحليل مع انسحاب متوقع r، يكون n/(1−r) تقريباً بسيطاً للاستقطاب تحت افتراضات معلنة، مع التقريب للأعلى. قارن سيناريوهات معقولة للأثر والانسحاب. لا تستبدل فترات التقدير أو التبرير الأولي بقوة محسوبة بعد النتائج.']),
 ('التوثيق القابل لإعادة الحساب',['احفظ الأداة والنسخة والاختبار وكل المدخلات ومصادر الافتراضات ونتائج السيناريوهات. فسّر كفاية العدد بالنسبة لنتيجة وافتراضات محددة، لا بوصفه رقماً عاماً. يتطلب القرار النهائي مراجعة التصميم والموارد الفعلية.'])],['تطابق الاختبار والتصميم.','تبرير الأثر والدقة.','مراعاة التجمع والانسحاب.','حفظ المدخلات وسيناريوهات الحساسية.']))

